css:
@property --apr-kds-heat { syntax: "<color>"; inherits: true; initial-value: oklch(0.76 0.15 155); }
@property --apr-kds-p { syntax: "<number>"; inherits: true; initial-value: 0; }

.apr-kds {
  --apr-kds-bg: oklch(0.17 0.008 70);
  --apr-kds-ink: oklch(0.95 0.012 85);
  --apr-kds-accent: oklch(0.87 0.17 96);
  --apr-kds-ok: oklch(0.76 0.15 155);
  --apr-kds-warn: oklch(0.83 0.15 78);
  --apr-kds-late: oklch(0.66 0.2 27);
  --apr-kds-panel: color-mix(in oklch, var(--apr-kds-bg), var(--apr-kds-ink) 5%);
  --apr-kds-card: color-mix(in oklch, var(--apr-kds-bg), var(--apr-kds-ink) 9%);
  --apr-kds-line: color-mix(in oklch, var(--apr-kds-ink) 11%, transparent);
  --apr-kds-line2: color-mix(in oklch, var(--apr-kds-ink) 22%, transparent);
  --apr-kds-mute: color-mix(in oklch, var(--apr-kds-ink) 58%, var(--apr-kds-bg));
  --apr-kds-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-kds-spring: linear(0, .07 4%, .26 9%, .55 15%, .83 22%, .98 29%, 1.04 35%, 1.05 40%, 1.02 50%, 1 62%, .997 78%, 1);
  --apr-kds-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-kds-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-kds;
  overflow: clip; isolation: isolate; border-radius: 14px;
  background: var(--apr-kds-bg); color: var(--apr-kds-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apr-kds-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apr-kds-accent); outline-offset: 2px; border-radius: 6px; }
  & h2 { margin: 0; text-wrap: balance; }
  & kbd { font: 600 10px/1 var(--apr-kds-mono); padding: 3px 5px 2px; min-width: 18px; text-align: center; display: inline-block; border-radius: 4px; border: 1px solid var(--apr-kds-line2); border-bottom-width: 2px; color: var(--apr-kds-mute); }

  & .apr-kds-app { height: 100%; display: grid; grid-template: "top top" auto "rail side" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) 272px; }

  /* ── top bar ── */
  & .apr-kds-top { grid-area: top; display: flex; align-items: center; gap: 16px; padding: 10px 16px; border-bottom: 1px solid var(--apr-kds-line); background: var(--apr-kds-panel); min-width: 0; }
  & .apr-kds-brand { display: flex; align-items: center; gap: 8px; flex: none;
    & svg { width: 22px; height: 22px; color: var(--apr-kds-accent); }
    & b { font-weight: 800; font-size: 15px; letter-spacing: -.01em; }
    & span { font-size: 12px; color: var(--apr-kds-mute); }
  }
  & .apr-kds-stations { display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--apr-kds-bg); border: 1px solid var(--apr-kds-line); min-width: 0; overflow-x: auto; scrollbar-width: none;
    & button { flex: none; display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 11px; border-radius: 7px; font-size: 13px; font-weight: 600; color: var(--apr-kds-mute); transition: background-color .2s, color .2s; }
    & button:hover { color: var(--apr-kds-ink); background: var(--apr-kds-card); }
    & button[aria-selected="true"] { background: var(--apr-kds-ink); color: var(--apr-kds-bg); }
    & i { width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
    & b { font: 700 11px/1 var(--apr-kds-mono); font-variant-numeric: tabular-nums; opacity: .7; }
  }
  & .apr-kds-stats { margin-left: auto; display: flex; gap: 14px; font-size: 12px; color: var(--apr-kds-mute); white-space: nowrap;
    & b { display: block; font: 700 15px/1.1 var(--apr-kds-mono); font-variant-numeric: tabular-nums; color: var(--apr-kds-ink); }
    & .is-late b { color: var(--apr-kds-late); }
  }
  & .apr-kds-intake { display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px 0 8px; border-radius: 999px; border: 1px solid var(--apr-kds-line2); font-size: 12px; color: var(--apr-kds-mute); white-space: nowrap;
    & i { width: 26px; height: 16px; border-radius: 999px; background: var(--apr-kds-ok); position: relative; transition: background-color .25s; }
    & i::after { content: ""; position: absolute; top: 2px; left: 12px; width: 12px; height: 12px; border-radius: 50%; background: var(--apr-kds-bg); transition: translate .35s var(--apr-kds-spring); }
    & b { color: var(--apr-kds-ink); font-weight: 650; }
    &[aria-checked="false"] i { background: var(--apr-kds-line2); }
    &[aria-checked="false"] i::after { translate: -10px 0; }
  }
  & .apr-kds-clock { font: 700 18px/1 var(--apr-kds-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }

  /* ── narrow view switcher ── */
  & .apr-kds-views { grid-area: views; display: none; gap: 4px; padding: 8px 12px; border-bottom: 1px solid var(--apr-kds-line);
    & button { flex: 1; height: 34px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--apr-kds-mute); }
    & button[aria-selected="true"] { background: var(--apr-kds-card); color: var(--apr-kds-ink); }
    & b { font: 700 11px var(--apr-kds-mono); margin-left: 4px; color: var(--apr-kds-accent); }
  }

  /* ── ticket rail ── */
  & .apr-kds-rail { grid-area: rail; min-height: 0; overflow-y: auto; padding: 14px; scrollbar-width: thin; scrollbar-color: var(--apr-kds-line2) transparent; position: relative; }
  & .apr-kds-paused { display: flex; align-items: center; gap: 8px; margin: 0 0 12px; padding: 8px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--apr-kds-warn); background: color-mix(in oklch, var(--apr-kds-warn) 12%, transparent); border: 1px dashed color-mix(in oklch, var(--apr-kds-warn) 45%, transparent);
    & svg { width: 16px; height: 16px; }
  }
  & .apr-kds-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(212px, 1fr)); gap: 12px; align-items: start; }
  & .apr-kds-empty { display: grid; justify-items: center; gap: 4px; margin: 80px auto 0; text-align: center; color: var(--apr-kds-mute);
    & svg { width: 40px; height: 40px; color: var(--apr-kds-ok); margin-bottom: 6px; }
    & b { color: var(--apr-kds-ink); font-size: 16px; }
  }

  /* one ticket — the colour is a clock: a --goal-long animation started --age seconds ago */
  & .apr-kds-tk {
    --apr-kds-heat: var(--apr-kds-ok);
    position: relative; display: grid; border-radius: 10px; overflow: clip; background: var(--apr-kds-card);
    border: 1px solid var(--apr-kds-line);
    animation: apr-kds-age calc(var(--goal) * 1s) linear forwards, apr-kds-in .5s var(--apr-kds-spring) backwards;
    animation-delay: calc(var(--age) * -1s), calc(var(--i, 0) * 40ms);
    transition: opacity .25s, translate .3s var(--apr-kds-ease), box-shadow .25s, filter .25s;
    &.is-sel { box-shadow: 0 0 0 2px var(--apr-kds-accent), 0 12px 28px -12px oklch(0 0 0 / .8); translate: 0 -2px; }
    &[data-hold] { --apr-kds-heat: oklch(0.62 0.02 250); animation-play-state: paused, running; }
    &.is-out { opacity: 0; translate: 0 -14px; filter: blur(2px); pointer-events: none; transition-duration: .22s; }
  }
  &[data-hl] .apr-kds-tk:not(.is-hl) { opacity: .32; filter: saturate(.3); }
  & .apr-kds-tk-head { display: grid; grid-template-columns: auto 1fr auto; grid-template-rows: auto auto; column-gap: 8px; align-items: baseline; padding: 9px 11px 8px; text-align: left; width: 100%;
    background: color-mix(in oklch, var(--apr-kds-heat) 88%, black); color: oklch(0.16 0.02 70); border-radius: 0;
    & .apr-kds-tk-no { grid-row: span 2; align-self: center; font: 700 11px/1 var(--apr-kds-mono); width: 22px; height: 22px; display: grid; place-items: center; border-radius: 6px; background: oklch(0 0 0 / .14); }
    & b { font-size: 17px; font-weight: 800; letter-spacing: -.015em; line-height: 1.1; }
    & .apr-kds-time { font: 750 19px/1 var(--apr-kds-mono); font-variant-numeric: tabular-nums; letter-spacing: -.03em; text-align: right; }
    & .apr-kds-tk-meta { grid-column: 2 / -1; display: flex; align-items: center; gap: 5px; font-size: 11.5px; font-weight: 600; opacity: .78; }
    & .apr-kds-tk-meta svg { width: 13px; height: 13px; stroke-width: 2; }
    & .apr-kds-goal { margin-left: auto; font: 600 10.5px var(--apr-kds-mono); }
  }
  & .apr-kds-tk[data-late] .apr-kds-tk-head { animation: apr-kds-throb 1.6s ease-in-out infinite; }
  & .apr-kds-tk[data-hold] .apr-kds-tk-head { color: var(--apr-kds-ink); }
  & .apr-kds-bar { height: 3px; background: color-mix(in oklch, var(--apr-kds-heat) 30%, transparent);
    &::before { content: ""; display: block; height: 100%; background: var(--apr-kds-heat); transform-origin: 0 50%; transform: scaleX(var(--apr-kds-p)); }
  }
  & .apr-kds-items { list-style: none; margin: 0; padding: 6px; display: grid; gap: 2px;
    & button { width: 100%; display: grid; grid-template-columns: 26px 1fr auto; gap: 8px; align-items: start; text-align: left; padding: 6px 6px; border-radius: 7px; transition: background-color .15s; }
    & button:hover { background: color-mix(in oklch, var(--apr-kds-ink) 6%, transparent); }
    & .q { font: 800 14px/22px var(--apr-kds-mono); text-align: center; border-radius: 5px; background: var(--apr-kds-bg); font-variant-numeric: tabular-nums; }
    & .n { min-width: 0; display: grid; gap: 1px; }
    & .n > b { font-size: 14px; font-weight: 700; line-height: 22px; display: flex; align-items: center; gap: 6px; }
    & .n > b i { width: 6px; height: 6px; flex: none; border-radius: 50%; background: var(--c); }
    & .temp { font: 800 11px/1 var(--apr-kds-mono); padding: 3px 4px; border-radius: 4px; background: var(--apr-kds-accent); color: var(--apr-kds-bg); letter-spacing: .02em; }
    & .mod { font-size: 12px; color: var(--apr-kds-warn); }
    & .mod::before { content: "→ "; opacity: .6; }
    & .alg { display: flex; align-items: center; gap: 5px; margin-top: 3px; padding: 3px 6px; border-radius: 5px; font-size: 11px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: oklch(0.98 0.01 30); background: var(--apr-kds-late); width: fit-content; }
    & .alg svg { width: 12px; height: 12px; stroke-width: 2.2; }
    & .ok { width: 18px; height: 18px; margin-top: 2px; border-radius: 50%; border: 1.5px solid var(--apr-kds-line2); display: grid; place-items: center; color: transparent; transition: background-color .2s, border-color .2s, color .2s; }
    & .ok svg { width: 12px; height: 12px; stroke-width: 2.6; }
    & button[aria-pressed="true"] { opacity: .5;
      & .n > b { text-decoration: line-through; text-decoration-thickness: 2px; text-decoration-color: var(--apr-kds-ok); }
      & .ok { background: var(--apr-kds-ok); border-color: var(--apr-kds-ok); color: var(--apr-kds-bg); }
    }
  }
  & .apr-kds-other { margin: 0 12px 4px; font-size: 11.5px; color: var(--apr-kds-mute); }
  & .apr-kds-tk-foot { display: flex; gap: 6px; padding: 0 8px 8px;
    & button { flex: 1; height: 34px; border-radius: 7px; font-size: 13px; font-weight: 700; display: flex; align-items: center; justify-content: center; gap: 8px; background: var(--apr-kds-bg); border: 1px solid var(--apr-kds-line2); transition: background-color .15s, border-color .15s; }
    & button:hover { border-color: var(--apr-kds-heat); background: color-mix(in oklch, var(--apr-kds-heat) 14%, var(--apr-kds-bg)); }
    & button kbd { border-color: currentColor; color: inherit; opacity: .6; }
    & button svg { width: 16px; height: 16px; flex: none; }
    & .is-fire { background: var(--apr-kds-accent); color: var(--apr-kds-bg); border-color: transparent; }
    & .is-fire:hover { background: color-mix(in oklch, var(--apr-kds-accent) 85%, white); }
  }

  /* ── side ── */
  & .apr-kds-side { grid-area: side; min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto; border-left: 1px solid var(--apr-kds-line); background: var(--apr-kds-panel); }
  & .apr-kds-side h2 { display: flex; align-items: baseline; justify-content: space-between; font-size: 11px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; padding: 14px 16px 8px;
    & span { font-size: 11px; letter-spacing: 0; text-transform: none; font-weight: 500; color: var(--apr-kds-mute); }
  }
  & .apr-kds-allday { min-height: 0; overflow-y: auto; scrollbar-width: thin;
    & ul { list-style: none; margin: 0; padding: 0 8px 12px; display: grid; gap: 1px; }
    & button { width: 100%; display: grid; grid-template-columns: 34px 1fr; gap: 10px; align-items: center; text-align: left; padding: 7px 8px; border-radius: 8px; transition: background-color .15s; }
    & button:hover { background: var(--apr-kds-card); }
    & button[aria-pressed="true"] { background: color-mix(in oklch, var(--apr-kds-accent) 16%, var(--apr-kds-card)); box-shadow: inset 2px 0 0 var(--apr-kds-accent); }
    & .q { font: 800 20px/1 var(--apr-kds-mono); font-variant-numeric: tabular-nums; text-align: right; }
    & .n { display: grid; min-width: 0; font-size: 13.5px; }
    & .n b { font-weight: 650; }
    & .n span { font-size: 11.5px; font-weight: 500; color: var(--apr-kds-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .n i { display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: var(--c); margin-right: 6px; vertical-align: 2px; }
    & .is-none { padding: 18px 10px; color: var(--apr-kds-mute); font-size: 13px; }
  }
  & .apr-kds-done { border-top: 1px solid var(--apr-kds-line);
    & ol { list-style: none; margin: 0; padding: 0 8px 10px; display: grid; gap: 2px; }
    & li { display: grid; grid-template-columns: 1fr auto auto; gap: 10px; align-items: center; padding: 5px 8px; border-radius: 8px; font-size: 13px; }
    & li:hover { background: var(--apr-kds-card); }
    & .t { font: 600 12.5px var(--apr-kds-mono); font-variant-numeric: tabular-nums; color: var(--apr-kds-mute); }
    & .t.is-late { color: var(--apr-kds-late); }
    & button { height: 26px; padding: 0 9px; border-radius: 6px; font-size: 12px; font-weight: 650; border: 1px solid var(--apr-kds-line2); display: flex; align-items: center; gap: 5px; }
    & button svg { width: 13px; height: 13px; }
    & button:hover { border-color: var(--apr-kds-accent); color: var(--apr-kds-accent); }
    & .is-none { padding: 6px 8px 12px; color: var(--apr-kds-mute); font-size: 13px; }
  }

  /* ── keys + toast ── */
  & .apr-kds-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 18px; padding: 8px 16px; border-top: 1px solid var(--apr-kds-line); font-size: 12px; color: var(--apr-kds-mute); background: var(--apr-kds-panel);
    & span { display: flex; align-items: center; gap: 4px; }
  }
  & .apr-kds-toast { position: absolute; left: 50%; bottom: 52px; z-index: 20; display: flex; align-items: center; gap: 14px; padding: 9px 10px 9px 16px; border-radius: 10px; background: var(--apr-kds-ink); color: var(--apr-kds-bg); font-size: 13px; font-weight: 600; box-shadow: 0 18px 40px -12px oklch(0 0 0 / .7);
    translate: -50% 16px; opacity: 0; pointer-events: none; transition: translate .4s var(--apr-kds-spring), opacity .2s;
    & button { padding: 5px 10px; border-radius: 6px; font-size: 12.5px; font-weight: 750; background: color-mix(in oklch, var(--apr-kds-bg) 12%, transparent); }
    &:not(.has-undo) button { display: none; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }

  @supports (animation-timeline: scroll()) {
    timeline-scope: --apr-kds-rail;
    & .apr-kds-rail { scroll-timeline: --apr-kds-rail y; }
    & .apr-kds-top { animation: apr-kds-lift linear both; animation-timeline: --apr-kds-rail; animation-range: 0 60px; }
  }

  @container apr-kds (max-width: 1200px) {
    & .apr-kds-stats > :nth-child(3) { display: none; }
    & .apr-kds-brand span { display: none; }
  }
  @container apr-kds (max-width: 959px) {
    & .apr-kds-app { grid-template-columns: minmax(0, 1fr) 228px; }
    & .apr-kds-top { flex-wrap: wrap; row-gap: 8px; }
    & .apr-kds-stations { order: 5; flex-basis: 100%; }
    & .apr-kds-stats { display: none; }
    & .apr-kds-intake { margin-left: auto; }
  }
  @container apr-kds (max-width: 759px) {
    & .apr-kds-app { grid-template: "top" auto "views" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
    & .apr-kds-views { display: flex; }
    & .apr-kds-keys { display: none; }
    & .apr-kds-rail, & .apr-kds-side { grid-area: main; }
    & .apr-kds-side { border-left: 0; background: none; grid-template-rows: minmax(0, 1fr); }
    &[data-view="rail"] .apr-kds-side, &:not([data-view="rail"]) .apr-kds-rail { display: none; }
    &[data-view="allday"] .apr-kds-done, &[data-view="bumped"] .apr-kds-allday { display: none; }
    &[data-view="bumped"] .apr-kds-done { border-top: 0; overflow-y: auto; }
    & .apr-kds-toast { bottom: 16px; }
    & .apr-kds-intake span { display: none; }
    & .apr-kds-intake { padding: 0 8px; }
  }
  @container apr-kds (max-width: 440px) {
    & .apr-kds-grid { grid-template-columns: minmax(0, 1fr); }
    & .apr-kds-clock { font-size: 15px; }
    & .apr-kds-rail { padding: 10px; }
  }

  @media (prefers-reduced-motion: reduce) {
    & .apr-kds-tk { animation: apr-kds-age calc(var(--goal) * 1s) linear forwards; animation-delay: calc(var(--age) * -1s); transition: opacity .2s; }
    & .apr-kds-tk.is-sel, & .apr-kds-tk.is-out { translate: none; filter: none; }
    & .apr-kds-tk[data-late] .apr-kds-tk-head { animation: none; box-shadow: inset 0 -3px 0 oklch(0 0 0 / .25); }
    & .apr-kds-toast, & .apr-kds-intake i::after { transition: opacity .2s; }
    & .apr-kds-top { animation: none; }
  }
}

@keyframes apr-kds-age {
  0% { --apr-kds-heat: var(--apr-kds-ok); --apr-kds-p: 0; }
  60% { --apr-kds-heat: var(--apr-kds-ok); }
  72% { --apr-kds-heat: var(--apr-kds-warn); }
  93% { --apr-kds-heat: var(--apr-kds-warn); }
  100% { --apr-kds-heat: var(--apr-kds-late); --apr-kds-p: 1; }
}
@keyframes apr-kds-in { from { opacity: 0; translate: 0 -18px; scale: .97; } }
@keyframes apr-kds-throb { 50% { filter: brightness(1.18) saturate(1.15); } }
@keyframes apr-kds-lift { to { box-shadow: 0 10px 24px -14px oklch(0 0 0 / .9); } }

js:
/* ── Fennick's line display. Each ticket's colour is a CSS animation that is --goal seconds long and
   started --age seconds ago, so the browser crossfades green → amber → red by itself. JS only
   rewrites mm:ss once a second and flags data-late when a ticket passes its goal. ── */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const mmss = s => { s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0'); };
const NOW = () => Date.now();

const IC = {
  dine: '<path d="M4 9h16M6.5 9v10M17.5 9v10M8.5 13.5h7"/><path d="M8 9V6.5M16 9V6.5"/>',
  togo: '<path d="M5.5 8.5h13l-1.2 11.5H6.7L5.5 8.5Z"/><path d="M9 8.5V7a3 3 0 0 1 6 0v1.5"/>',
  bar: '<path d="M6.5 4h11l-1.3 6.8a4.3 4.3 0 0 1-8.4 0L6.5 4Z"/><path d="M12 15v5M8.5 20h7"/>',
  alert: '<path d="M12 4 2.8 20h18.4L12 4Z"/><path d="M12 10v4.2M12 17.2v.3"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7"/>',
  recall: '<path d="M9.5 14.5 4.5 9.5l5-5"/><path d="M4.5 9.5h10a5.5 5.5 0 0 1 0 11h-3"/>',
  fire: '<path d="M12 21c-3.6 0-6-2.4-6-5.8 0-3.2 2.4-5.2 3.6-8.2.4 1.9 1.5 3 2.6 3.4.2-2.2 1.1-4.4 3-6.1-.3 2.8.8 4.5 2.1 6.4.6 1.3.8 2.8.6 4.5C17.5 18.8 15.3 21 12 21Z"/>'
};
const svg = (k, cls) => '<svg viewBox="0 0 24 24" aria-hidden="true"' + (cls ? ' class="' + cls + '"' : '') + '>' + IC[k] + '</svg>';

const ST = { grill: ['Grill', 'oklch(0.7 0.17 38)'], saute: ['Sauté', 'oklch(0.78 0.13 88)'], fry: ['Fry', 'oklch(0.8 0.15 115)'], cold: ['Cold', 'oklch(0.76 0.1 205)'], pastry: ['Pastry', 'oklch(0.75 0.12 345)'] };
const M = {
  ribeye: ['Ribeye 14oz', 'grill'], chicken: ['Half chicken', 'grill'], lamb: ['Lamb chops', 'grill'], burger: ['Smash burger', 'grill'], pork: ['Pork chop', 'grill'], sword: ['Swordfish', 'grill'],
  rigatoni: ['Rigatoni vodka', 'saute'], mussels: ['Mussels', 'saute'], scallop: ['Seared scallops', 'saute'], risotto: ['Mushroom risotto', 'saute'],
  fries: ['Fries', 'fry'], calamari: ['Calamari', 'fry'], fish: ['Fish & chips', 'fry'], sprouts: ['Crispy sprouts', 'fry'],
  caesar: ['Caesar', 'cold'], burrata: ['Burrata', 'cold'], crudo: ['Hamachi crudo', 'cold'], wedge: ['Wedge', 'cold'],
  toffee: ['Sticky toffee', 'pastry'], panna: ['Panna cotta', 'pastry'], tart: ['Chocolate tart', 'pastry']
};
const TEMPS = { ribeye: 1, lamb: 1, burger: 1, pork: 1, sword: 1 };
let seq = 0;
const it = (k, q, temp, mods, alg) => ({ k, q, temp: temp || '', mods: mods || [], alg: alg || '', done: false });
const tk = (name, kind, cov, srv, age, goal, items, hold) => ({ id: 'k' + (++seq), name, kind, cov, srv, t0: NOW() - age * 1000, goal, items, hold: !!hold });

let S = {
  station: 'all', sel: null, hl: null, live: true,
  tickets: [
    tk('T7', 'dine', 2, 'Marisol', 704, 600, [it('ribeye', 1, 'MR'), it('chicken', 1), it('fries', 2, '', ['extra crispy'])]),
    tk('T22', 'dine', 4, 'Devon', 486, 600, [it('lamb', 1, 'M'), it('rigatoni', 1), it('caesar', 2, '', ['no anchovy']), it('fries', 1)]),
    tk('A208', 'togo', 0, 'Pickup 7:40', 371, 720, [it('burger', 2, 'MW', ['no onion', 'add bacon']), it('fish', 1), it('sprouts', 1)]),
    tk('T3', 'dine', 6, 'Marisol', 270, 840, [it('sword', 1), it('scallop', 2), it('risotto', 1, '', ['no pine nut'], 'Tree nut allergy'), it('ribeye', 1, 'MW'), it('pork', 1, 'M')]),
    tk('Bar 2', 'bar', 2, 'Luca', 135, 480, [it('calamari', 1), it('burrata', 1), it('crudo', 1, '', [], 'Gluten free')]),
    tk('T15', 'dine', 2, 'Devon', 65, 600, [it('wedge', 1, '', ['dressing on side']), it('burger', 1, 'MR')]),
    tk('T9', 'dine', 3, 'Priya', 190, 600, [it('chicken', 1), it('ribeye', 1, 'R'), it('mussels', 1, '', ['extra bread'])], true),
    tk('T11', 'dine', 3, 'Priya', 40, 360, [it('toffee', 1), it('panna', 2)])
  ],
  bumped: [
    { name: 'T18', secs: 492, t: null }, { name: 'A205', secs: 587, t: null }, { name: 'T4', secs: 423, t: null }
  ]
};
S.sel = S.tickets[0].id;
const past = [];
const snap = () => { past.push(JSON.stringify(S)); if (past.length > 40) past.shift(); };

const grid = $('.apr-kds-grid'), rail = $('.apr-kds-rail');
const forStation = (t, st = S.station) => t.items.filter(x => st === 'all' || M[x.k][1] === st);
const visible = () => S.tickets.filter(t => forStation(t).some(x => !x.done));
const age = t => (NOW() - t.t0) / 1000;

/* ── toast ── */
const toastEl = $('.apr-kds-toast');
let toastT = 0;
function toast(msg, undoable) {
  $('[data-msg]', toastEl).textContent = msg;
  toastEl.classList.toggle('has-undo', !!undoable);
  toastEl.classList.add('is-on');
  clearTimeout(toastT);
  toastT = setTimeout(() => toastEl.classList.remove('is-on'), 3600);
}

/* ── render ── */
function renderStations() {
  const opts = [['all', 'Expo', 'var(--apr-kds-accent)']].concat(Object.keys(ST).map(k => [k, ST[k][0], ST[k][1]]));
  $('.apr-kds-stations').innerHTML = opts.map(([k, n, c]) => {
    const count = S.tickets.filter(t => forStation(t, k).some(x => !x.done)).length;
    return '<button type="button" role="tab" data-st="' + k + '" aria-selected="' + (S.station === k) + '" style="--c:' + c + '"><i aria-hidden="true"></i>' + n + ' <b>' + count + '</b></button>';
  }).join('');
}
function renderStats() {
  const v = S.tickets, late = v.filter(t => !t.hold && age(t) >= t.goal).length;
  const last = S.bumped.slice(0, 10), avg = last.length ? last.reduce((s, b) => s + b.secs, 0) / last.length : 0;
  const covers = v.reduce((s, t) => s + t.cov, 0);
  $('.apr-kds-stats').innerHTML =
    '<span>Open<b>' + v.length + '</b></span>' +
    '<span class="' + (late ? 'is-late' : '') + '">Late<b>' + late + '</b></span>' +
    '<span>Covers<b>' + covers + '</b></span>' +
    '<span>Avg bump<b>' + mmss(avg) + '</b></span>';
  $('[data-c="open"]').textContent = visible().length;
  $('[data-c="bumped"]').textContent = S.bumped.length;
}
function itemHTML(t, x) {
  const j = t.items.indexOf(x), [n, st] = M[x.k];
  return '<li><button type="button" data-act="item" data-j="' + j + '" aria-pressed="' + x.done + '" aria-label="' + esc(x.q + ' ' + n + (x.temp ? ' ' + x.temp : '') + (x.done ? ', done' : '')) + '">' +
    '<span class="q">' + x.q + '</span><span class="n"><b>' + (S.station === 'all' ? '<i style="--c:' + ST[st][1] + '"></i>' : '') + esc(n) + (x.temp ? ' <span class="temp">' + x.temp + '</span>' : '') + '</b>' +
    x.mods.map(m => '<span class="mod">' + esc(m) + '</span>').join('') +
    (x.alg ? '<span class="alg">' + svg('alert') + esc(x.alg) + '</span>' : '') +
    '</span><span class="ok">' + svg('check') + '</span></button></li>';
}
function ticketHTML(t, i) {
  const its = forStation(t), other = t.items.length - its.length, a = age(t), sel = t.id === S.sel;
  const hl = S.hl && its.some(x => x.k === S.hl && !x.done);
  return '<article role="listitem" class="apr-kds-tk' + (sel ? ' is-sel' : '') + (hl ? ' is-hl' : '') + '" data-k="' + t.id + '"' + (t.hold ? ' data-hold' : '') + (!t.hold && a >= t.goal ? ' data-late' : '') +
    ' style="--goal:' + t.goal + ';--age:' + (t.hold ? 0 : a.toFixed(2)) + ';--i:' + i + '">' +
    '<button type="button" class="apr-kds-tk-head" data-act="sel" aria-pressed="' + sel + '" aria-label="Ticket ' + esc(t.name) + '">' +
    '<span class="apr-kds-tk-no">' + (i + 1) + '</span><b>' + esc(t.name) + '</b><span class="apr-kds-time" data-t>' + (t.hold ? 'HOLD' : mmss(a)) + '</span>' +
    '<span class="apr-kds-tk-meta">' + svg(t.kind) + (t.cov ? t.cov + ' cov · ' : '') + esc(t.srv) + '<span class="apr-kds-goal">' + (t.hold ? 'mains on call' : 'goal ' + mmss(t.goal)) + '</span></span></button>' +
    '<i class="apr-kds-bar" aria-hidden="true"></i>' +
    '<ol class="apr-kds-items">' + its.map(x => itemHTML(t, x)).join('') + '</ol>' +
    (other ? '<p class="apr-kds-other">+' + other + ' item' + (other > 1 ? 's' : '') + ' on other stations</p>' : '') +
    '<div class="apr-kds-tk-foot">' + (t.hold
      ? '<button type="button" class="is-fire" data-act="fire">' + svg('fire') + 'Fire mains <kbd>F</kbd></button>'
      : '<button type="button" data-act="bump">' + (S.station === 'all' ? 'Bump ticket' : 'Bump ' + ST[S.station][0]) + ' <kbd>&crarr;</kbd></button>') +
    '</div></article>';
}
function renderRail() {
  const v = visible();
  if (v.length && !v.some(t => t.id === S.sel)) S.sel = v[0].id;
  if (S.hl && !v.some(t => forStation(t).some(x => x.k === S.hl && !x.done))) S.hl = null;
  root.toggleAttribute('data-hl', !!S.hl);
  grid.innerHTML = v.map(ticketHTML).join('');
  $('.apr-kds-empty').hidden = v.length > 0;
}
function ticketsFor(k) {
  const n = S.tickets.filter(t => !t.hold && forStation(t).some(x => x.k === k && !x.done)).length;
  return n > 1 ? 'across ' + n + ' tickets' : 'one ticket';
}
function renderAllDay() {
  const map = new Map();
  S.tickets.forEach(t => forStation(t).forEach(x => {
    if (x.done) return;
    const r = map.get(x.k) || { q: 0, held: 0, temps: {} };
    if (t.hold) r.held += x.q; else { r.q += x.q; if (x.temp) r.temps[x.temp] = (r.temps[x.temp] || 0) + x.q; }
    map.set(x.k, r);
  }));
  const rows = [...map.entries()].sort((a, b) => (b[1].q + b[1].held) - (a[1].q + a[1].held));
  $('.apr-kds-allday [data-st]').textContent = S.station === 'all' ? 'All stations' : ST[S.station][0];
  $('.apr-kds-allday ul').innerHTML = rows.length ? rows.map(([k, r]) => {
    const sub = Object.entries(r.temps).map(([tt, q]) => tt + ' ' + q).concat(r.held ? ['+' + r.held + ' held'] : []).join(' · ');
    return '<li><button type="button" data-act="hl" data-key="' + k + '" aria-pressed="' + (S.hl === k) + '"><span class="q">' + (r.q || r.held) + '</span><span class="n"><b><i style="--c:' + ST[M[k][1]][1] + '"></i>' + esc(M[k][0]) + '</b><span>' + (sub || ticketsFor(k)) + '</span></span></button></li>';
  }).join('') : '<li class="is-none">Nothing all day on this station.</li>';
}
function renderBumped() {
  $('.apr-kds-done ol').innerHTML = S.bumped.length ? S.bumped.slice(0, 6).map((b, i) =>
    '<li><b>' + esc(b.name) + '</b><span class="t' + (b.goal && b.secs > b.goal ? ' is-late' : '') + '">' + mmss(b.secs) + '</span>' +
    (b.t ? '<button type="button" data-act="recall" data-i="' + i + '" title="Put ' + esc(b.name) + ' back on the rail">' + svg('recall') + 'Recall</button>'
         : '<button type="button" disabled title="Closed before this shift opened on this screen">' + svg('recall') + 'Recall</button>') + '</li>').join('')
    : '<li class="is-none">Nothing bumped yet.</li>';
}
function render() { renderStations(); renderStats(); renderRail(); renderAllDay(); renderBumped(); }

/* FLIP the rail around a state change: survivors glide, newcomers drop in via CSS */
function flipRail(mutate) {
  const first = new Map($$('.apr-kds-tk', grid).map(e => [e.dataset.k, e.getBoundingClientRect()]));
  mutate();
  if (RM.matches) return;
  $$('.apr-kds-tk', grid).forEach(e => {
    const f = first.get(e.dataset.k); if (!f) return;
    e.style.setProperty('--i', 0);
    const l = e.getBoundingClientRect(), dx = f.left - l.left, dy = f.top - l.top;
    if (Math.abs(dx) + Math.abs(dy) < 1) { e.style.animationName = 'apr-kds-age'; return; }
    e.style.animationName = 'apr-kds-age';
    e.animate([{ transform: 'translate(' + dx + 'px,' + dy + 'px)' }, { transform: 'none' }], { duration: 460, easing: 'cubic-bezier(.2,.8,.2,1)' });
  });
}
const quiet = () => $$('.apr-kds-tk', grid).forEach(e => { e.style.animationName = 'apr-kds-age'; });

/* ── actions ── */
const T = id => S.tickets.find(t => t.id === id);
function select(id, focus) {
  S.sel = id;
  $$('.apr-kds-tk', grid).forEach(e => { const on = e.dataset.k === id; e.classList.toggle('is-sel', on); $('.apr-kds-tk-head', e).setAttribute('aria-pressed', on); });
  const el = grid.querySelector('[data-k="' + id + '"]');
  if (el) { el.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' }); if (focus) $('.apr-kds-tk-head', el).focus({ preventScroll: true }); }
}
function toggleItem(t, j) {
  const x = t.items[j]; if (!x) return;
  snap();
  x.done = !x.done;
  const left = forStation(t).filter(y => !y.done).length;
  if (!left) { bump(t, true); return; }
  renderStations(); renderAllDay();
  const el = grid.querySelector('[data-k="' + t.id + '"] [data-j="' + j + '"]');
  if (el) { el.setAttribute('aria-pressed', x.done); }
  toast((x.done ? 'Struck ' : 'Restored ') + x.q + ' × ' + M[x.k][0] + ' · ' + t.name, true);
}
function bump(t, already) {
  if (!t || t.hold) return;
  if (!already) snap();
  const st = S.station, el = grid.querySelector('[data-k="' + t.id + '"]');
  forStation(t, st).forEach(x => { x.done = true; });
  const finished = t.items.every(x => x.done);
  if (finished) {
    S.tickets = S.tickets.filter(x => x !== t);
    S.bumped.unshift({ name: t.name, secs: Math.round(age(t)), goal: t.goal, t: JSON.parse(JSON.stringify(t)) });
    S.bumped = S.bumped.slice(0, 12);
  }
  const msg = finished ? 'Bumped ' + t.name + ' in ' + mmss(age(t)) : t.name + ' · ' + ST[st][0] + ' done, still on the rail for other stations';
  const go = () => { flipRail(render); toast(msg, true); };
  if (el && !RM.matches) { el.classList.add('is-out'); setTimeout(go, 200); } else go();
}
function fire(t) {
  if (!t || !t.hold) return;
  snap();
  t.hold = false; t.t0 = NOW();
  render(); quiet(); select(t.id);
  toast('Fired mains for ' + t.name + ' · clock started', true);
}
function recall(i) {
  const b = S.bumped[i]; if (!b || !b.t) return;
  snap();
  const t = b.t; t.items.forEach(x => { x.done = false; });
  S.bumped.splice(i, 1);
  S.tickets.push(t); S.sel = t.id;
  if (S.station !== 'all' && !forStation(t).length) S.station = 'all';
  flipRail(render); select(t.id);
  toast('Recalled ' + t.name + ' · ' + mmss(age(t)) + ' on the clock', true);
}
function undo() {
  if (!past.length) { toast('Nothing to undo'); return; }
  S = JSON.parse(past.pop());
  flipRail(render); applyIntake();
  toast('Undone');
}
function applyIntake() {
  const b = $('.apr-kds-intake');
  b.setAttribute('aria-checked', S.live);
  $('b', b).textContent = S.live ? 'Live' : 'Paused';
  $('.apr-kds-paused').hidden = S.live;
}

root.addEventListener('click', e => {
  const t = e.target;
  const st = t.closest('[data-st]');
  if (st && st.closest('.apr-kds-stations')) { S.station = st.dataset.st; S.hl = null; render(); rail.scrollTop = 0; return; }
  const v = t.closest('.apr-kds-views [data-v]');
  if (v) { root.dataset.view = v.dataset.v; $$('.apr-kds-views [data-v]').forEach(b => b.setAttribute('aria-selected', b === v)); return; }
  if (t.closest('.apr-kds-intake')) { snap(); S.live = !S.live; applyIntake(); toast(S.live ? 'Online orders resumed' : 'Online orders paused for this station', true); return; }
  const a = t.closest('[data-act]'); if (!a) return;
  const act = a.dataset.act, card = a.closest('.apr-kds-tk'), tt = card && T(card.dataset.k);
  if (act === 'undo') undo();
  else if (act === 'sel') select(tt.id);
  else if (act === 'item') { select(tt.id); toggleItem(tt, +a.dataset.j); }
  else if (act === 'bump') bump(tt);
  else if (act === 'fire') fire(tt);
  else if (act === 'recall') recall(+a.dataset.i);
  else if (act === 'hl') { S.hl = S.hl === a.dataset.key ? null : a.dataset.key; renderRail(); quiet(); renderAllDay(); const n = $$('.apr-kds-tk.is-hl', grid); if (n[0]) select(n[0].dataset.k); }
});

root.addEventListener('keydown', e => {
  const t = e.target;
  if (t.matches('input, textarea, select')) return;
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); undo(); return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const v = visible(), i = v.findIndex(x => x.id === S.sel), cur = v[i];
  const k = e.key.toLowerCase();
  if (e.key === 'ArrowRight' || e.key === 'ArrowLeft' || e.key === 'ArrowDown' || e.key === 'ArrowUp') {
    if (t.closest('.apr-kds-stations, .apr-kds-views')) {
      const tabs = $$('[role="tab"]', t.closest('[role="tablist"]')), n = tabs.indexOf(t.closest('[role="tab"]'));
      const nx = tabs[(n + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : tabs.length - 1)) % tabs.length];
      e.preventDefault(); nx.focus(); nx.click(); return;
    }
    if (!v.length) return;
    e.preventDefault();
    const d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;
    select(v[Math.max(0, Math.min(v.length - 1, i + d))].id, true);
  } else if (/^[1-9]$/.test(e.key) && cur) {
    const its = forStation(cur), x = its[+e.key - 1];
    if (x) { e.preventDefault(); toggleItem(cur, cur.items.indexOf(x)); }
  } else if ((e.key === 'Enter' || e.key === ' ') && cur && (t === root || t.closest('.apr-kds-tk-head'))) {
    e.preventDefault(); cur.hold ? fire(cur) : bump(cur);
  } else if (k === 'f' && cur) { fire(cur.hold ? cur : v.find(x => x.hold)); }
  else if (k === 'r') { const n = S.bumped.findIndex(b => b.t); if (n > -1) recall(n); else toast('Nothing to recall yet'); }
  else if (e.key === 'Escape' && S.hl) { S.hl = null; renderRail(); quiet(); renderAllDay(); }
});

/* ── new tickets print while the screen is visible; the clock ticks once a second ── */
const POOL = [
  ['dine', ['ribeye', 'fries', 'caesar']], ['dine', ['chicken', 'sprouts']], ['togo', ['burger', 'fries', 'fish']], ['bar', ['calamari', 'crudo']],
  ['dine', ['lamb', 'risotto', 'wedge']], ['dine', ['scallop', 'mussels', 'burrata']], ['togo', ['rigatoni', 'caesar']], ['dine', ['tart', 'toffee']]
];
const SRV = ['Marisol', 'Devon', 'Priya', 'Luca'];
const MODS = ['no onion', 'sauce on side', 'sub greens', 'add egg', 'light salt'];
let poolI = 0, pickup = 211, onScreen = true, ticks = 0;
function arrive() {
  const [kind, keys] = POOL[poolI++ % POOL.length];
  if (kind === 'togo' && !S.live) return;
  if (visible().length >= 11) return;
  const used = new Set(S.tickets.map(t => t.name));
  let name = kind === 'togo' ? 'A' + (pickup++) : kind === 'bar' ? 'Bar ' + (1 + poolI % 6) : 'T' + (2 + (poolI * 7) % 23);
  if (used.has(name)) name += 'b';
  const items = keys.map((k, n) => it(k, 1 + ((poolI + n) % 3 === 0 ? 1 : 0), TEMPS[k] ? ['MR', 'M', 'MW', 'R'][(poolI + n) % 4] : '', (poolI + n) % 4 === 1 ? [MODS[(poolI + n) % MODS.length]] : []));
  const dessert = keys.every(k => M[k][1] === 'pastry');
  const t = tk(name, kind, kind === 'togo' ? 0 : 2 + poolI % 3, kind === 'togo' ? 'Pickup ' + (8 + Math.floor(poolI / 6)) + ':' + String((poolI * 5) % 60).padStart(2, '0') : SRV[poolI % SRV.length], 0, dessert ? 360 : kind === 'bar' ? 480 : 600, items);
  S.tickets.push(t);
  flipRail(() => { renderStations(); renderStats(); renderRail(); renderAllDay(); });
  toast('New ticket · ' + name + (t.cov ? ' · ' + t.cov + ' covers' : ' · pickup'));
}
function tick() {
  const d = new Date();
  $('.apr-kds-clock').textContent = String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
  $$('.apr-kds-tk', grid).forEach(el => {
    const t = T(el.dataset.k); if (!t || t.hold) return;
    const a = age(t), tx = $('[data-t]', el), s = mmss(a);
    if (tx.textContent !== s) tx.textContent = s;
    const late = a >= t.goal;
    if (late !== el.hasAttribute('data-late')) { el.toggleAttribute('data-late', late); renderStats(); }
  });
}
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); return; }
  if (!onScreen || document.hidden) return;
  tick();
  if (++ticks % 21 === 0) arrive();
}, 1000);

render(); applyIntake(); tick();

css:
.apr-floor {
  --apr-floor-bg: oklch(0.968 0.011 85);
  --apr-floor-ink: oklch(0.27 0.026 55);
  --apr-floor-accent: oklch(0.6 0.14 40);
  --apr-floor-wood: oklch(0.915 0.026 78);
  --apr-floor-card: color-mix(in oklch, var(--apr-floor-bg), white 72%);
  --apr-floor-line: color-mix(in oklch, var(--apr-floor-ink) 11%, transparent);
  --apr-floor-line2: color-mix(in oklch, var(--apr-floor-ink) 22%, transparent);
  --apr-floor-mute: color-mix(in oklch, var(--apr-floor-ink) 58%, var(--apr-floor-bg));
  --apr-floor-tint: color-mix(in oklch, var(--apr-floor-accent) 12%, var(--apr-floor-card));
  --apr-floor-s-open: oklch(0.66 0.1 150);
  --apr-floor-s-seated: oklch(0.78 0.12 88);
  --apr-floor-s-ordered: oklch(0.72 0.13 62);
  --apr-floor-s-mains: oklch(0.62 0.14 38);
  --apr-floor-s-dessert: oklch(0.56 0.11 350);
  --apr-floor-s-check: oklch(0.5 0.05 255);
  --apr-floor-s-dirty: oklch(0.66 0.012 80);
  --apr-floor-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-floor-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-floor-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --apr-floor-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-floor-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-floor;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apr-floor-line);
  background: var(--apr-floor-bg); color: var(--apr-floor-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--apr-floor-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apr-floor-accent); outline-offset: 2px; border-radius: 8px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & kbd { font: 600 10px/1 var(--apr-floor-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apr-floor-line2); border-bottom-width: 2px; background: var(--apr-floor-card); color: var(--apr-floor-mute); }

  & .apr-floor-app { height: 100%; display: grid; grid-template: "top top" auto "stage side" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) 318px; }

  /* ── header ── */
  & .apr-floor-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 10px 18px; border-bottom: 1px solid var(--apr-floor-line); background: var(--apr-floor-card); }
  & .apr-floor-brand { display: flex; align-items: center; gap: 9px; flex: none;
    & svg { width: 24px; height: 24px; color: var(--apr-floor-accent); }
    & b { font: 600 21px/1 var(--apr-floor-serif); letter-spacing: -.01em; }
    & span { font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apr-floor-mute); padding-left: 9px; border-left: 1px solid var(--apr-floor-line2); }
  }
  & .apr-floor-rooms { display: flex; gap: 4px;
    & button { height: 32px; padding: 0 13px; border-radius: 999px; font-size: 13px; font-weight: 600; color: var(--apr-floor-mute); border: 1px solid transparent; transition: background-color .2s, color .2s, border-color .2s; }
    & button:hover { color: var(--apr-floor-ink); border-color: var(--apr-floor-line2); }
    & button[aria-selected="true"] { background: var(--apr-floor-ink); color: var(--apr-floor-bg); }
    & small { font: 600 11px var(--apr-floor-mono); opacity: .7; margin-left: 4px; }
  }
  & .apr-floor-stats { margin-left: auto; display: flex; gap: 18px; font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--apr-floor-mute); white-space: nowrap;
    & b { display: block; font: 700 18px/1.1 system-ui, sans-serif; letter-spacing: -.01em; text-transform: none; color: var(--apr-floor-ink); font-variant-numeric: tabular-nums; }
    & b small { font-size: 12px; font-weight: 500; color: var(--apr-floor-mute); }
    & .apr-floor-meter { display: block; width: 86px; height: 4px; margin-top: 4px; border-radius: 2px; background: var(--apr-floor-line); overflow: hidden; }
    & .apr-floor-meter i { display: block; height: 100%; width: calc(var(--v) * 100%); background: var(--apr-floor-accent); border-radius: 2px; transition: width .6s var(--apr-floor-ease); }
  }
  & .apr-floor-secbtn { display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--apr-floor-line2); font-size: 13px; font-weight: 600; transition: background-color .2s, border-color .2s;
    & svg { width: 17px; height: 17px; }
    &:hover { border-color: var(--apr-floor-ink); }
    &[aria-pressed="true"] { background: var(--apr-floor-tint); border-color: var(--apr-floor-accent); color: color-mix(in oklch, var(--apr-floor-accent) 70%, var(--apr-floor-ink)); }
  }
  & .apr-floor-views { grid-area: views; display: none; gap: 4px; padding: 8px 12px; border-bottom: 1px solid var(--apr-floor-line); background: var(--apr-floor-card);
    & button { flex: 1; height: 34px; border-radius: 8px; font-weight: 600; font-size: 13px; color: var(--apr-floor-mute); }
    & button[aria-selected="true"] { background: var(--apr-floor-ink); color: var(--apr-floor-bg); }
    & b { font: 700 11px var(--apr-floor-mono); margin-left: 4px; }
  }

  /* ── stage + plan: every measure inside the plan is in cqi of the plan, so the room scales as one drawing ── */
  & .apr-floor-stage { grid-area: stage; min-height: 0; overflow: auto; padding: 14px 18px 12px; display: flex; flex-direction: column; gap: 10px; scrollbar-width: thin; }
  & .apr-floor-hint { min-height: 34px; display: flex; align-items: center; gap: 10px; font-size: 13px; color: var(--apr-floor-mute);
    & b { color: var(--apr-floor-ink); }
    & .apr-floor-hint-pill { display: inline-flex; align-items: center; gap: 8px; padding: 6px 8px 6px 12px; border-radius: 999px; background: var(--apr-floor-ink); color: var(--apr-floor-bg); font-weight: 600; animation: apr-floor-pop .4s var(--apr-floor-spring); }
    & .apr-floor-hint-pill button { height: 24px; padding: 0 10px; border-radius: 999px; font-size: 12px; font-weight: 700; background: color-mix(in oklch, var(--apr-floor-bg) 18%, transparent); }
  }
  & .apr-floor-plan { position: relative; flex: none; width: 100%; min-width: 540px; aspect-ratio: 100 / 62; container-type: inline-size; border-radius: 1.4cqi;
    background:
      repeating-linear-gradient(90deg, transparent 0 calc(7.6cqi - 1px), color-mix(in oklch, var(--apr-floor-ink) 6%, transparent) calc(7.6cqi - 1px) 7.6cqi),
      linear-gradient(color-mix(in oklch, var(--apr-floor-wood), white 18%), var(--apr-floor-wood));
    box-shadow: inset 0 0 0 .5cqi color-mix(in oklch, var(--apr-floor-ink) 78%, var(--apr-floor-wood)), 0 1px 0 var(--apr-floor-card);
  }
  &[data-room="patio"] .apr-floor-plan {
    background:
      repeating-conic-gradient(color-mix(in oklch, var(--apr-floor-ink) 5%, transparent) 0 25%, transparent 0 50%) 0 0 / 6cqi 6cqi,
      oklch(0.93 0.012 110);
  }
  & .apr-floor-decor { position: absolute; inset: 0; pointer-events: none; font-size: clamp(8px, 1.15cqi, 12px); font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: color-mix(in oklch, var(--apr-floor-ink) 45%, transparent);
    & .win { position: absolute; top: 0; height: .5cqi; background: repeating-linear-gradient(90deg, oklch(0.84 0.04 220) 0 3cqi, transparent 3cqi 3.6cqi); }
    & .bar { position: absolute; border-radius: 1cqi 0 0 1cqi; background: color-mix(in oklch, var(--apr-floor-ink) 74%, oklch(0.5 0.08 50)); color: var(--apr-floor-wood); display: grid; place-items: center; writing-mode: vertical-rl; }
    & .stool { position: absolute; width: 2.2cqi; aspect-ratio: 1; border-radius: 50%; border: .3cqi solid color-mix(in oklch, var(--apr-floor-ink) 40%, transparent); }
    & .lbl { position: absolute; display: flex; align-items: center; gap: .6cqi; }
    & .lbl::before { content: ""; width: 1.4cqi; height: 1.4cqi; border: .3cqi solid currentColor; border-radius: .3cqi; }
    & .door { position: absolute; width: 7cqi; height: 7cqi; border-top: .4cqi solid currentColor; border-left: .25cqi dashed currentColor; border-radius: 0 0 0 100%; }
    & .plant { position: absolute; width: 3.4cqi; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle at 40% 35%, oklch(0.72 0.1 140), oklch(0.5 0.09 145)); box-shadow: 0 .3cqi .6cqi oklch(0.4 0.05 140 / .3); }
  }

  /* tables */
  & .apr-floor-t {
    --c: var(--apr-floor-s-open);
    position: absolute; left: calc(var(--x) * 1cqi); top: calc(var(--y) * 1cqi); width: calc(var(--w) * 1cqi); height: calc(var(--h) * 1cqi);
    display: grid; place-items: center; z-index: 1;
    animation: apr-floor-in .5s var(--apr-floor-spring) backwards; animation-delay: calc(var(--i, 0) * 28ms);
    transition: scale .3s var(--apr-floor-spring), opacity .25s, filter .25s;
    &[data-st="seated"] { --c: var(--apr-floor-s-seated); } &[data-st="ordered"] { --c: var(--apr-floor-s-ordered); }
    &[data-st="mains"] { --c: var(--apr-floor-s-mains); } &[data-st="dessert"] { --c: var(--apr-floor-s-dessert); }
    &[data-st="check"] { --c: var(--apr-floor-s-check); } &[data-st="dirty"] { --c: var(--apr-floor-s-dirty); }
    &:hover { scale: 1.04; z-index: 3; }
    &:focus-visible { outline: none; }
    &:focus-visible .apr-floor-tb { outline: .45cqi solid var(--apr-floor-accent); outline-offset: .5cqi; }
    &.is-sel { z-index: 4; }
    &.is-sel .apr-floor-tb { box-shadow: 0 0 0 .5cqi var(--apr-floor-bg), 0 0 0 .95cqi var(--apr-floor-ink), 0 1.2cqi 2.4cqi -1cqi oklch(0.3 0.04 50 / .5); }
  }
  & .apr-floor-tb { position: relative; z-index: 1; width: 100%; height: 100%; display: grid; place-content: center; text-align: center; gap: .15cqi; padding: .4cqi;
    border-radius: 1.2cqi; background: color-mix(in oklch, var(--c) 22%, var(--apr-floor-card)); border: .4cqi solid var(--c);
    box-shadow: 0 .5cqi 1.2cqi -.6cqi oklch(0.3 0.04 50 / .35); transition: background-color .35s, border-color .35s, box-shadow .25s;
    & b { font: 750 clamp(11px, 2.1cqi, 22px)/1 system-ui, sans-serif; letter-spacing: -.02em; }
    & small { font-size: clamp(8px, 1.08cqi, 12px); font-weight: 600; line-height: 1.15; color: color-mix(in oklch, var(--apr-floor-ink) 78%, var(--c)); white-space: nowrap; max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
    & .m { font-family: var(--apr-floor-mono); font-variant-numeric: tabular-nums; }
  }
  & .apr-floor-t[data-shape="round"] .apr-floor-tb { border-radius: 50%; }
  & .apr-floor-t[data-shape="booth"] .apr-floor-tb { border-radius: .8cqi; }
  & .apr-floor-t[data-st="open"] .apr-floor-tb { background: var(--apr-floor-card); border-style: dashed; }
  & .apr-floor-t[data-st="dirty"] .apr-floor-tb { background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--c) 30%, var(--apr-floor-card)) 0 .5cqi, var(--apr-floor-card) .5cqi 1.2cqi); }
  & .apr-floor-ch { position: absolute; left: calc(var(--cx) * 1%); top: calc(var(--cy) * 1%); width: 2.1cqi; height: 2.1cqi; translate: -50% -50%; border-radius: 50%;
    background: var(--apr-floor-card); border: .3cqi solid color-mix(in oklch, var(--apr-floor-ink) 35%, transparent); transition: background-color .3s, border-color .3s;
    &.is-on { background: color-mix(in oklch, var(--apr-floor-ink) 82%, var(--c)); border-color: transparent; }
  }
  & .apr-floor-t[data-shape="booth"] .apr-floor-ch { border-radius: .6cqi; width: 2.6cqi; height: 3.6cqi; }
  & .apr-floor-t[data-shape="booth"]::before { content: ""; position: absolute; inset: -2.4cqi -1.2cqi; border-radius: 1.4cqi; background: color-mix(in oklch, var(--apr-floor-ink) 14%, var(--apr-floor-wood)); }
  & .apr-floor-t[data-shape="booth"] .apr-floor-ch { z-index: 0; }

  /* sections overlay */
  &[data-sections] .apr-floor-t::after { content: ""; position: absolute; inset: -2.6cqi; border-radius: 2cqi; background: color-mix(in oklch, var(--sec) 22%, transparent); border: .25cqi solid color-mix(in oklch, var(--sec) 60%, transparent); z-index: -1; animation: apr-floor-fade .35s var(--apr-floor-ease); }
  &[data-sections] .apr-floor-t[data-shape="round"]::after { border-radius: 50%; }

  /* seating: fitting tables lift, the rest step back */
  &[data-seating] .apr-floor-t[data-fit="no"], &[data-dragging] .apr-floor-t[data-fit="no"] { opacity: .38; filter: grayscale(.7); }
  &[data-seating] .apr-floor-t[data-fit="best"] .apr-floor-tb, &[data-dragging] .apr-floor-t[data-fit="best"] .apr-floor-tb { box-shadow: 0 0 0 .5cqi var(--apr-floor-bg), 0 0 0 1cqi var(--apr-floor-s-open); animation: apr-floor-breathe 1.4s ease-in-out infinite; }
  &[data-seating] .apr-floor-t[data-fit="ok"] .apr-floor-tb, &[data-dragging] .apr-floor-t[data-fit="ok"] .apr-floor-tb { box-shadow: 0 0 0 .5cqi var(--apr-floor-bg), 0 0 0 .8cqi color-mix(in oklch, var(--apr-floor-s-open) 55%, transparent); }
  & .apr-floor-t.is-over { scale: 1.12; z-index: 5; }
  & .apr-floor-t.is-over .apr-floor-tb { background: color-mix(in oklch, var(--apr-floor-s-open) 30%, var(--apr-floor-card)); }

  /* table card */
  & .apr-floor-pop { position: absolute; z-index: 8; width: 268px; padding: 14px; border-radius: 14px; background: var(--apr-floor-card); border: 1px solid var(--apr-floor-line);
    box-shadow: 0 24px 48px -18px oklch(0.25 0.04 50 / .45), 0 2px 6px oklch(0.25 0.04 50 / .08);
    transition: opacity .2s, scale .35s var(--apr-floor-spring); transform-origin: var(--ox, 50%) var(--oy, 0%);
    @starting-style { opacity: 0; scale: .92; }
    & header { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
    & header h3 { font: 600 20px/1 var(--apr-floor-serif); }
    & header span { font-size: 12px; color: var(--apr-floor-mute); }
    & .x { margin-left: auto; width: 28px; height: 28px; border-radius: 8px; display: grid; place-items: center; color: var(--apr-floor-mute); }
    & .x:hover { background: var(--apr-floor-line); color: var(--apr-floor-ink); }
    & .x svg { width: 16px; height: 16px; }
    & .who { display: grid; grid-template-columns: 1fr auto; gap: 2px 10px; padding: 10px 12px; border-radius: 10px; background: var(--apr-floor-bg); margin-bottom: 12px; }
    & .who b { font-size: 15px; } & .who .m { font: 700 15px var(--apr-floor-mono); text-align: right; font-variant-numeric: tabular-nums; }
    & .who span { font-size: 12px; color: var(--apr-floor-mute); }
    & .steps { list-style: none; margin: 0 0 12px; padding: 0; display: grid; grid-template-columns: repeat(5, 1fr); gap: 3px; }
    & .steps button { width: 100%; display: grid; gap: 5px; justify-items: center; font-size: 10.5px; font-weight: 650; color: var(--apr-floor-mute); padding: 4px 0; border-radius: 6px; }
    & .steps button::before { content: ""; width: 100%; height: 5px; border-radius: 3px; background: var(--apr-floor-line); transition: background-color .3s; }
    & .steps button.is-past::before, & .steps button[aria-current="step"]::before { background: var(--apr-floor-s-c, var(--apr-floor-ink)); }
    & .steps button[aria-current="step"] { color: var(--apr-floor-ink); }
    & .steps button:hover { background: var(--apr-floor-bg); }
    & .acts { display: flex; gap: 6px; flex-wrap: wrap; }
    & .acts button { flex: 1; height: 34px; padding: 0 10px; border-radius: 9px; font-size: 13px; font-weight: 650; border: 1px solid var(--apr-floor-line2); white-space: nowrap; }
    & .acts button:hover { border-color: var(--apr-floor-ink); }
    & .acts .is-primary { background: var(--apr-floor-ink); color: var(--apr-floor-bg); border-color: transparent; }
    & .acts.walk { align-items: center; flex-wrap: nowrap; }
    & .acts.walk span { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apr-floor-mute); margin-right: 4px; }
    & .acts.walk button { flex: 0 0 34px; padding: 0; font: 700 13px var(--apr-floor-mono); }
    & .steps button:disabled { cursor: default; }
    & .fits { display: grid; gap: 4px; margin: 0 0 10px; padding: 0; list-style: none; }
    & .fits button { width: 100%; display: flex; align-items: center; gap: 8px; padding: 7px 10px; border-radius: 8px; border: 1px solid var(--apr-floor-line); font-size: 13px; text-align: left; }
    & .fits button:hover { border-color: var(--apr-floor-s-open); background: color-mix(in oklch, var(--apr-floor-s-open) 10%, var(--apr-floor-card)); }
    & .fits .sz { font: 700 12px var(--apr-floor-mono); width: 22px; height: 22px; border-radius: 6px; display: grid; place-items: center; background: var(--apr-floor-bg); }
    & .fits small { margin-left: auto; color: var(--apr-floor-mute); font-size: 11.5px; }
    & .none { font-size: 12.5px; color: var(--apr-floor-mute); margin: 0 0 10px; text-wrap: pretty; }
  }

  & .apr-floor-legend { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 11.5px; color: var(--apr-floor-mute);
    & li { display: flex; align-items: center; gap: 6px; }
    & i { width: 10px; height: 10px; border-radius: 3px; background: color-mix(in oklch, var(--c) 30%, var(--apr-floor-card)); border: 2px solid var(--c); }
    & .is-srv i { border-radius: 50%; background: var(--c); border: 0; }
    & .is-srv b { color: var(--apr-floor-ink); font-variant-numeric: tabular-nums; }
    & .is-next { color: var(--apr-floor-ink); font-weight: 650; }
  }

  /* ── waitlist ── */
  & .apr-floor-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--apr-floor-line); background: var(--apr-floor-card); overflow-y: auto; scrollbar-width: thin; }
  & .apr-floor-sidehead { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; gap: 10px; padding: 14px 16px 10px; background: var(--apr-floor-card);
    & h2 { font: 600 19px/1 var(--apr-floor-serif); display: flex; align-items: baseline; gap: 8px; }
    & h2 span { font: 700 12px var(--apr-floor-mono); color: var(--apr-floor-mute); }
  }
  & .apr-floor-addbtn { margin-left: auto; white-space: nowrap; flex: none; display: flex; align-items: center; gap: 6px; height: 32px; padding: 0 12px 0 9px; border-radius: 9px; background: var(--apr-floor-accent); color: oklch(0.99 0.01 80); font-size: 13px; font-weight: 650; transition: background-color .2s;
    & svg { width: 16px; height: 16px; stroke-width: 2.2; }
    &:hover { background: color-mix(in oklch, var(--apr-floor-accent) 88%, black); }
    &[aria-expanded="true"] { background: var(--apr-floor-ink); }
  }
  & .apr-floor-form { margin: 0 12px 10px; padding: 12px; border-radius: 12px; background: var(--apr-floor-bg); display: grid; gap: 10px; border: 1px solid var(--apr-floor-line);
    transition: opacity .2s, translate .35s var(--apr-floor-spring);
    @starting-style { opacity: 0; translate: 0 -8px; }
    & .apr-floor-field { display: grid; gap: 4px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apr-floor-mute); }
    & input[name="name"] { height: 36px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--apr-floor-line2); background: var(--apr-floor-card); font-size: 14px; letter-spacing: 0; text-transform: none; color: var(--apr-floor-ink); }
    & input[name="name"]:focus { outline: 2px solid var(--apr-floor-accent); outline-offset: 0; border-color: transparent; }
    & input[aria-invalid="true"] { border-color: oklch(0.58 0.19 27); background: oklch(0.97 0.02 27); }
    & .apr-floor-row { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; }
    & .apr-floor-size { display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 9px; border: 1px solid var(--apr-floor-line2); background: var(--apr-floor-card);
      & > span { font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apr-floor-mute); padding: 0 6px; }
      & button { width: 28px; height: 28px; border-radius: 6px; font-size: 16px; font-weight: 700; }
      & button:hover { background: var(--apr-floor-line); }
      & output { min-width: 22px; text-align: center; font: 700 15px var(--apr-floor-mono); font-variant-numeric: tabular-nums; }
    }
