/* ── Larkhollow host stand. The plan is one drawing measured in cqi of itself, so it scales as a unit.
   Drag a waiting party onto the room (or press Seat, then arrows + Enter): every table is graded
   best / ok / no for that party before you let go. Quotes come from what each table is doing now. ── */
const $ = (s, el = root) => el.querySelector(s);
