  x: '<path d="M6 6l12 12M18 6 6 18"/>', seat: '<path d="M7 4v9h10M7 13l-1 7M17 13l1 7M7 9h7"/>', text: '<path d="M5 5h14v10H9l-4 4V5Z"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7"/>'
