const SRV = { A: ['Priya', 'oklch(0.66 0.14 32)'], B: ['Marco', 'oklch(0.6 0.1 285)'], C: ['Jun', 'oklch(0.62 0.11 160)'], D: ['Ines', 'oklch(0.72 0.13 85)'] };
const STATES = ['seated', 'ordered', 'mains', 'dessert', 'check'];
const SNAME = { open: 'Open', seated: 'Seated', ordered: 'Ordered', mains: 'Mains', dessert: 'Dessert', check: 'Check', dirty: 'Dirty' };
/* minutes until a table in this state is likely free again */
const FREE_IN = { open: 0, dirty: 4, check: 8, dessert: 16, mains: 30, ordered: 44, seated: 56 };
const ROOMS = { main: 'Dining room', patio: 'Patio' };
const P = (name, size, ago, extra) => Object.assign({ name, size, t0: NOW() - ago * MIN }, extra || {});
const TB = (id, room, shape, seats, x, y, w, h, sec, st, party) => ({ id, room, shape, seats, x, y, w, h, sec, st: st || 'open', party: party || null });

let S = {
  room: 'main', sel: null, seating: null, sections: false, wsel: null, form: false, size: 2,
  tables: [
    TB('T1', 'main', 'booth', 4, 3, 6, 13, 8, 'A', 'mains', P('Okafor', 4, 48)),
    TB('T2', 'main', 'booth', 4, 3, 23, 13, 8, 'A', 'dessert', P('Lindqvist', 3, 71)),
    TB('T3', 'main', 'booth', 4, 3, 40, 13, 8, 'A'),
    TB('T4', 'main', 'sq', 4, 24, 6, 8, 8, 'A', 'ordered', P('Haddad', 4, 18)),
    TB('T5', 'main', 'sq', 4, 24, 24, 8, 8, 'B', 'check', P('Moreau', 2, 84)),
