    TB('T7', 'main', 'sq', 4, 38, 24, 8, 8, 'B', 'seated', P('Nakamura', 4, 4)),
    TB('T8', 'main', 'sq', 2, 54, 5, 6, 6, 'C', 'mains', P('Reyes', 2, 35)),
    TB('T9', 'main', 'sq', 2, 54, 19, 6, 6, 'C'),
    TB('T10', 'main', 'sq', 2, 67, 19, 6, 6, 'C', 'seated', P('Abiola', 2, 9)),
    TB('T11', 'main', 'sq', 2, 67, 5, 6, 6, 'C'),
    TB('T12', 'main', 'round', 8, 22, 43, 12, 12, 'B', 'ordered', P('Castellanos', 7, 22, { note: 'Birthday' })),
    TB('T13', 'main', 'round', 6, 40, 44, 10, 10, 'C'),
    TB('T14', 'main', 'rect', 6, 55, 35, 16, 7, 'C', 'mains', P('Brennan', 6, 41)),
    TB('P1', 'patio', 'sq', 4, 9, 9, 8, 8, 'D', 'seated', P('Varga', 3, 12)),
    TB('P2', 'patio', 'sq', 4, 27, 9, 8, 8, 'D'),
    TB('P3', 'patio', 'sq', 2, 45, 10, 6, 6, 'D'),
    TB('P4', 'patio', 'round', 6, 9, 33, 10, 10, 'D', 'dessert', P('Oyelaran', 5, 66)),
