  if (t.st === 'dirty') return t.id + ' still needs to be reset';
  if (t.st !== 'open') return t.id + ' is occupied · ' + SNAME[t.st].toLowerCase();
  if (t.seats < p.size) return t.id + ' seats ' + t.seats + ' · party of ' + p.size + ' won’t fit';
