  const pool = S.tables.filter(t => t.seats >= size && t.seats <= size + 3 && (pref === 'booth' ? t.shape === 'booth' : pref === 'patio' ? t.room === 'patio' : true));
  if (!pool.length) return null;
  const times = pool.map(t => Math.max(t.st === 'open' ? 0 : 3, FREE_IN[t.st] - (t.party ? Math.round(mins(t.party.t0) * 0.25) : 0))).sort((a, b) => a - b);
  const q = times[Math.min(ahead, times.length - 1)] + (ahead >= times.length ? 20 : 0);
  return Math.max(5, Math.ceil(q / 5) * 5);
}
const aheadOf = size => S.wait.filter(w => Math.abs(w.size - size) <= 2).length;

/* chair positions as % of the table box */
function chairs(t) {
  if (t.shape === 'round') return Array.from({ length: t.seats }, (_, i) => { const a = i / t.seats * Math.PI * 2 - Math.PI / 2; return [50 + 68 * Math.cos(a), 50 + 68 * Math.sin(a)]; });
  if (t.shape === 'booth') return [[27, -22], [73, -22], [27, 122], [73, 122]];
  if (t.shape === 'rect') return [[18, -30], [50, -30], [82, -30], [18, 130], [50, 130], [82, 130]];
  return t.seats === 2 ? [[-26, 50], [126, 50]] : [[50, -24], [124, 50], [50, 124], [-24, 50]];
}

/* ── toast ── */
const toastEl = $('.apr-floor-toast');
let toastT = 0;
function toast(msg, undoable) {
