}

/* ── render ── */
let dragP = null;
function decor() {
  if (S.room === 'patio') return '<span class="plant" style="left:2cqi;top:2cqi"></span><span class="plant" style="left:56cqi;top:2cqi"></span><span class="plant" style="left:2cqi;top:55cqi"></span><span class="plant" style="left:94cqi;top:55cqi"></span>' +
    '<span class="lbl" style="left:64cqi;top:6cqi">Heaters on</span><span class="lbl" style="left:64cqi;top:50cqi">Garden gate</span><span class="door" style="left:84cqi;top:0;rotate:90deg"></span>';
  let st = '';
  for (let i = 0; i < 8; i++) st += '<span class="stool" style="left:79cqi;top:' + (6 + i * 5) + 'cqi"></span>';
  return '<span class="win" style="left:50cqi;width:30cqi"></span><span class="bar" style="left:83cqi;top:4cqi;width:8cqi;height:42cqi">Bar</span>' + st +
    '<span class="lbl" style="left:60cqi;top:53cqi">Host stand</span><span class="lbl" style="left:83cqi;top:51cqi">Kitchen</span><span class="door" style="left:74cqi;top:55cqi"></span>';
}
function tableHTML(t, i) {
