  const small = p ? '<small>' + esc(p.name) + '</small><small class="m" data-t0="' + p.t0 + '">' + mins(p.t0) + 'm</small>' : '<small>' + (t.st === 'dirty' ? 'Reset' : t.seats + '-top') + '</small>';
  const label = t.id + ', ' + t.seats + ' seats, ' + SNAME[t.st] + (p ? ', ' + p.name + ' party of ' + p.size : '') + ', ' + SRV[t.sec][0];
  return '<button type="button" class="apr-floor-t' + (S.sel === t.id ? ' is-sel' : '') + '" data-t="' + t.id + '" data-shape="' + t.shape + '" data-st="' + t.st + '"' + (fit ? ' data-fit="' + fit + '"' : '') +
    ' style="--x:' + t.x + ';--y:' + t.y + ';--w:' + t.w + ';--h:' + t.h + ';--i:' + i + ';--sec:' + SRV[t.sec][1] + '" aria-label="' + esc(label) + '">' + ch +
    '<span class="apr-floor-tb"><b>' + t.id + '</b>' + small + '</span></button>';
}
function renderPlan(anim) {
