  layer.innerHTML = S.tables.filter(t => t.room === S.room).map(tableHTML).join('');
  if (!anim) $$('.apr-floor-t', layer).forEach(e => { e.style.animation = 'none'; });
  renderPop();
}
function renderRooms() {
  $('.apr-floor-rooms').innerHTML = Object.entries(ROOMS).map(([k, n]) => {
    const open = S.tables.filter(t => t.room === k && t.st === 'open').length;
    return '<button type="button" role="tab" data-room="' + k + '" aria-selected="' + (S.room === k) + '">' + n + '<small>' + open + ' open</small></button>';
  }).join('');
}
function renderStats() {
  const seats = S.tables.reduce((s, t) => s + t.seats, 0), cov = S.tables.reduce((s, t) => s + (t.party ? t.party.size : 0), 0);
  const open = S.tables.filter(t => t.st === 'open').length, dirty = S.tables.filter(t => t.st === 'dirty').length;
  const longest = S.wait.reduce((m, w) => Math.max(m, mins(w.t0)), 0);
