  --apr-order-tint: color-mix(in oklch, var(--apr-order-gold) 22%, var(--apr-order-card));
  --apr-order-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-order-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-order-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-order-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-order;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apr-order-line);
  background: var(--apr-order-bg); color: var(--apr-order-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--apr-order-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apr-order-accent); outline-offset: 2px; border-radius: 8px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--apr-order-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apr-order-line2); border-bottom-width: 2px; color: var(--apr-order-mute); background: var(--apr-order-card); }

  & .apr-order-app { height: 100%; display: grid; grid-template: "top top top" auto "cats menu bag" minmax(0, 1fr) / 172px minmax(0, 1fr) 352px; }

  /* ── header ── */
  & .apr-order-top { grid-area: top; position: relative; z-index: 6; display: flex; align-items: center; gap: 16px; padding: 12px 18px; border-bottom: 1px solid var(--apr-order-line); background: var(--apr-order-card); }
  & .apr-order-brand { display: flex; align-items: baseline; gap: 7px; flex: none;
    & svg { width: 24px; height: 24px; color: var(--apr-order-gold); stroke-width: 2; align-self: center; }
    & b { font-size: 19px; font-weight: 850; letter-spacing: -.035em; }
    & span { font-size: 12px; font-weight: 600; color: var(--apr-order-mute); letter-spacing: .02em; }
  }
  & .apr-order-where { display: flex; align-items: center; gap: 6px; margin: 0; font-size: 12.5px; color: var(--apr-order-mute); white-space: nowrap;
    & svg { width: 16px; height: 16px; color: var(--apr-order-accent); }
    & b { color: var(--apr-order-ink); font-weight: 600; }
  }
  & .apr-order-search { margin-left: auto; display: flex; align-items: center; gap: 8px; height: 36px; width: min(260px, 30cqi); padding: 0 8px 0 11px; border-radius: 10px; background: var(--apr-order-bg); border: 1px solid var(--apr-order-line); transition: border-color .2s, box-shadow .2s;
    & svg { width: 16px; height: 16px; color: var(--apr-order-mute); flex: none; }
    & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 13.5px; }
    &:focus-within { border-color: var(--apr-order-ink); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apr-order-gold) 35%, transparent); }
  }
  & .apr-order-avoidbtn { display: flex; align-items: center; gap: 7px; height: 36px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--apr-order-line2); font-size: 13px; font-weight: 600; white-space: nowrap;
    & svg { width: 16px; height: 16px; }
    & b { font: 700 11px/1 var(--apr-order-mono); min-width: 18px; height: 18px; padding: 0 5px; display: grid; place-items: center; border-radius: 9px; background: var(--apr-order-accent); color: white; }
    &:hover, &[aria-expanded="true"] { border-color: var(--apr-order-ink); }
  }
  & .apr-order-avoid { position: absolute; right: 18px; top: calc(100% + 6px); width: 320px; padding: 14px; border-radius: 14px; background: var(--apr-order-card); border: 1px solid var(--apr-order-line); box-shadow: 0 22px 44px -18px oklch(0.25 0.04 50 / .45);
    transition: opacity .2s, translate .35s var(--apr-order-spring); @starting-style { opacity: 0; translate: 0 -6px; }
    & p { margin: 0 0 10px; font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apr-order-mute); }
    & small { display: block; margin-top: 10px; font-size: 12px; color: var(--apr-order-mute); text-wrap: pretty; }
  }
  & .apr-order-avoid-list { display: flex; flex-wrap: wrap; gap: 6px;
    & button { height: 30px; padding: 0 11px; border-radius: 999px; border: 1px solid var(--apr-order-line2); font-size: 12.5px; font-weight: 600; display: flex; align-items: center; gap: 6px; transition: background-color .15s, color .15s, border-color .15s; }
    & button:hover { border-color: var(--apr-order-ink); }
    & button[aria-pressed="true"] { background: var(--apr-order-ink); color: var(--apr-order-bg); border-color: transparent; }
    & button[aria-pressed="true"]::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--apr-order-accent); }
  }

  /* ── categories ── */
  & .apr-order-cats { grid-area: cats; min-height: 0; overflow-y: auto; padding: 16px 10px; display: flex; flex-direction: column; gap: 2px; border-right: 1px solid var(--apr-order-line);
    & button { display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 36px; padding: 0 12px; border-radius: 9px; font-size: 13.5px; font-weight: 600; color: var(--apr-order-mute); text-align: left; transition: background-color .2s, color .2s; position: relative; }
    & button:hover { color: var(--apr-order-ink); background: var(--apr-order-line); }
    & button[aria-current="true"] { color: var(--apr-order-ink); background: var(--apr-order-card); box-shadow: 0 1px 2px oklch(0.3 0.04 50 / .08), inset 0 0 0 1px var(--apr-order-line); }
    & button[aria-current="true"]::before { content: ""; position: absolute; left: -10px; top: 9px; bottom: 9px; width: 3px; border-radius: 0 3px 3px 0; background: var(--apr-order-accent); }
    & small { font: 600 11px var(--apr-order-mono); opacity: .7; }
  }

  /* ── menu ── */
  & .apr-order-menu { grid-area: menu; position: relative; min-height: 0; overflow-y: auto; padding: 4px 20px 28px; scroll-behavior: smooth; scroll-padding-top: 8px; scrollbar-width: thin; }
  & .apr-order-sec { padding-top: 18px; }
  & .apr-order-sec h2 { display: flex; align-items: baseline; gap: 10px; font-size: clamp(19px, 2.2cqi, 24px); font-weight: 800; letter-spacing: -.025em; margin-bottom: 4px; }
  & .apr-order-sec h2 small { font-size: 12.5px; font-weight: 500; letter-spacing: 0; color: var(--apr-order-mute); }
  & .apr-order-grid { list-style: none; margin: 10px 0 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(262px, 1fr)); gap: 10px; }
  & .apr-order-item { position: relative; display: grid; grid-template-columns: minmax(0, 1fr) 92px; gap: 10px; padding: 14px 12px 12px 14px; border-radius: 14px; background: var(--apr-order-card); border: 1px solid var(--apr-order-line); transition: border-color .2s, box-shadow .25s, opacity .25s;
    &:hover { border-color: var(--apr-order-line2); box-shadow: 0 14px 30px -22px oklch(0.3 0.05 50 / .7); }
    & h3 { font-size: 15px; font-weight: 700; letter-spacing: -.01em; line-height: 1.25; }
    & .ds { margin: 4px 0 8px; font-size: 12.5px; color: var(--apr-order-mute); line-height: 1.4; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
    & .meta { display: flex; flex-wrap: wrap; align-items: center; gap: 5px; font-size: 11px; }
    & .pr { font: 700 14px var(--apr-order-mono); font-variant-numeric: tabular-nums; margin-right: 4px; }
    & .tg { display: inline-flex; align-items: center; gap: 3px; height: 20px; padding: 0 6px; border-radius: 5px; font-weight: 650; background: var(--apr-order-bg); color: var(--apr-order-mute); }
    & .tg svg { width: 12px; height: 12px; }
    & .tg.veg { color: var(--apr-order-leaf); background: color-mix(in oklch, var(--apr-order-leaf) 12%, var(--apr-order-card)); }
    & .tg.hot { color: var(--apr-order-accent); background: color-mix(in oklch, var(--apr-order-accent) 10%, var(--apr-order-card)); }
    & .tg.pop { color: color-mix(in oklch, var(--apr-order-gold) 55%, var(--apr-order-ink)); background: var(--apr-order-tint); }
    & .art { position: relative; width: 92px; height: 92px; align-self: start; }
    & .art > svg { width: 100%; height: 100%; stroke: none; transition: rotate .8s var(--apr-order-spring); }
    &:hover .art > svg { rotate: 14deg; }
    & .als { flex-basis: 100%; margin-top: 2px; font-size: 11px; color: var(--apr-order-mute); letter-spacing: .01em; }
    & .add { position: absolute; right: -2px; bottom: -4px; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: var(--apr-order-ink); color: var(--apr-order-bg); box-shadow: 0 0 0 3px var(--apr-order-card); transition: scale .25s var(--apr-order-spring), background-color .2s; }
    & .add svg { width: 17px; height: 17px; stroke-width: 2.4; }
    & .add:hover { scale: 1.1; background: var(--apr-order-accent); }
    & .add:disabled { background: var(--apr-order-line2); color: var(--apr-order-mute); scale: 1; }
    & .inbag { position: absolute; left: -6px; top: -6px; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px; display: grid; place-items: center; font: 700 11px var(--apr-order-mono); background: var(--apr-order-accent); color: white; box-shadow: 0 0 0 2px var(--apr-order-card); }
    & .why { grid-column: 1 / -1; margin: 2px 0 0; display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 650; color: var(--apr-order-accent); }
    & .why svg { width: 14px; height: 14px; }
    &.is-off { opacity: .55; }
    &.is-off .art { filter: grayscale(1); opacity: .6; }
  }
  @supports (animation-timeline: view()) {
    & .apr-order-item { animation: apr-order-rise linear both; animation-timeline: view(); animation-range: entry 0% entry 55%; }
  }
  & .apr-order-noresult { margin: 60px auto; text-align: center; color: var(--apr-order-mute); max-width: 300px;
    & b { display: block; color: var(--apr-order-ink); font-size: 16px; margin-bottom: 4px; }
    & button { margin-top: 12px; height: 32px; padding: 0 14px; border-radius: 9px; border: 1px solid var(--apr-order-line2); font-weight: 600; font-size: 13px; }
  }

  /* ── bag ── */
  & .apr-order-bag { grid-area: bag; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--apr-order-line); background: var(--apr-order-card); }
  & .apr-order-baghead { display: flex; align-items: center; gap: 10px; padding: 16px 18px 10px;
    & h2 { font-size: 18px; font-weight: 800; letter-spacing: -.02em; }
    & span { font-size: 12.5px; color: var(--apr-order-mute); }
    & .back { display: none; width: 30px; height: 30px; border-radius: 8px; place-items: center; margin-left: -6px; }
    & .back svg { width: 18px; height: 18px; }
    & .clear { margin-left: auto; font-size: 12.5px; font-weight: 600; color: var(--apr-order-mute); padding: 4px 8px; border-radius: 6px; }
    & .clear:hover { color: var(--apr-order-accent); background: var(--apr-order-bg); }
  }
  & .apr-order-bagbody { flex: 1; min-height: 0; overflow-y: auto; padding: 0 18px 12px; scrollbar-width: thin; }
  & .apr-order-lines { list-style: none; margin: 0; padding: 0; display: grid; }
  & .apr-order-line { display: grid; grid-template-columns: 1fr auto; gap: 2px 10px; padding: 10px 0; border-bottom: 1px dashed var(--apr-order-line2);
    & b { font-size: 14px; font-weight: 650; }
    & .lp { font: 650 13.5px var(--apr-order-mono); font-variant-numeric: tabular-nums; text-align: right; }
    & .md { grid-column: 1; font-size: 12px; color: var(--apr-order-mute); line-height: 1.35; }
    & .md.warn { grid-column: 1 / -1; display: flex; align-items: center; gap: 5px; margin-top: 3px; color: var(--apr-order-accent); font-weight: 650; }
    & .md.warn svg { width: 13px; height: 13px; flex: none; }
    & .ctl { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin-top: 4px; }
    & .stp { display: flex; align-items: center; border-radius: 8px; border: 1px solid var(--apr-order-line2); }
    & .stp button { width: 28px; height: 26px; display: grid; place-items: center; font-size: 15px; font-weight: 700; border-radius: 7px; }
    & .stp button:hover { background: var(--apr-order-bg); }
    & .stp output { min-width: 20px; text-align: center; font: 700 12.5px var(--apr-order-mono); }
    & .lk { font-size: 12px; font-weight: 600; color: var(--apr-order-mute); padding: 4px 6px; border-radius: 6px; }
    & .lk:hover { color: var(--apr-order-ink); background: var(--apr-order-bg); }
    & .lk.rm:hover { color: var(--apr-order-accent); }
    &.is-new { animation: apr-order-flash 1.2s var(--apr-order-ease); }
  }
  & .apr-order-empty { margin: 30px 0; text-align: center; color: var(--apr-order-mute); font-size: 13px;
    & svg { width: 48px; height: 48px; margin: 0 auto 8px; color: var(--apr-order-line2); }
    & b { display: block; color: var(--apr-order-ink); font-size: 15px; }
  }

  /* the slot picker is the kitchen's load chart: booked units, your bag stacked on top */
  & .apr-order-slots { margin-top: 16px;
    & .hd { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
    & h3 { font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--apr-order-mute); }
    & .ready { font-size: 13px; font-weight: 650; }
    & .ready b { font-family: var(--apr-order-mono); color: var(--apr-order-accent); }
  }
  & .apr-order-chart { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 4px; align-items: end; }
  & .apr-order-slot { display: grid; gap: 4px; justify-items: center; padding: 4px 0 2px; border-radius: 8px; transition: background-color .2s;
    & .col { position: relative; width: 100%; height: 78px; border-radius: 5px; background: repeating-linear-gradient(0deg, var(--apr-order-line) 0 1px, transparent 1px 6.5px), var(--apr-order-bg); overflow: hidden; box-shadow: inset 0 0 0 1px var(--apr-order-line); }
    & .bk, & .me { position: absolute; left: 0; right: 0; bottom: 0; transition: height .5s var(--apr-order-spring), bottom .5s var(--apr-order-spring), background-color .2s; }
    & .bk { height: calc(var(--b) * 100%); background: color-mix(in oklch, var(--apr-order-ink) 32%, var(--apr-order-bg)); }
    & .me { bottom: calc(var(--b) * 100%); height: calc(var(--u) * 100%); background: color-mix(in oklch, var(--apr-order-gold) 55%, transparent); opacity: 0; transition: opacity .2s, height .5s var(--apr-order-spring); }
    & .tm { font: 600 10px/1 var(--apr-order-mono); font-variant-numeric: tabular-nums; color: var(--apr-order-mute); white-space: nowrap; letter-spacing: -.03em; }
    &:nth-child(even):not([aria-checked="true"]) .tm { visibility: hidden; }
    &:hover:not(:disabled) { background: var(--apr-order-bg); }
    &:hover:not(:disabled) .me { opacity: .7; }
    &[aria-checked="true"] { background: var(--apr-order-tint); }
    &[aria-checked="true"] .me { opacity: 1; background: var(--apr-order-accent); }
    &[aria-checked="true"] .tm { color: var(--apr-order-ink); font-weight: 750; }
    &:disabled .col { background: repeating-linear-gradient(135deg, var(--apr-order-line) 0 3px, transparent 3px 7px), var(--apr-order-bg); }
    &:disabled .bk { background: color-mix(in oklch, var(--apr-order-ink) 18%, var(--apr-order-bg)); }
    &:disabled .col::after { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 4px; background: var(--apr-order-accent); opacity: .8; }
    &:disabled .tm { text-decoration: line-through; opacity: .6; }
  }
  & .apr-order-slotnote { margin: 8px 0 0; font-size: 12px; color: var(--apr-order-mute); min-height: 2.8em; }
  & .apr-order-slotnote b { color: var(--apr-order-ink); }

  & .apr-order-tips { margin-top: 14px;
    & h3 { font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--apr-order-mute); margin-bottom: 8px; }
    & div { display: grid; grid-template-columns: repeat(4, 1fr); gap: 4px; padding: 3px; border-radius: 10px; background: var(--apr-order-bg); border: 1px solid var(--apr-order-line); }
    & button { height: 30px; border-radius: 7px; font-size: 12.5px; font-weight: 650; color: var(--apr-order-mute); }
    & button[aria-checked="true"] { background: var(--apr-order-card); color: var(--apr-order-ink); box-shadow: 0 1px 3px oklch(0.3 0.04 50 / .15); }
  }
  & .apr-order-sum { margin: 14px 0 0; display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; font-size: 13px;
    & dt { color: var(--apr-order-mute); } & dd { margin: 0; text-align: right; font-family: var(--apr-order-mono); font-variant-numeric: tabular-nums; }
    & .tot { font-size: 16px; font-weight: 800; color: var(--apr-order-ink); padding-top: 8px; border-top: 1px solid var(--apr-order-line2); margin-top: 4px; }
  }
  & .apr-order-cta { padding: 12px 18px 16px; border-top: 1px solid var(--apr-order-line); background: var(--apr-order-card);
    & button { width: 100%; height: 46px; border-radius: 12px; display: flex; align-items: center; justify-content: space-between; padding: 0 16px; background: var(--apr-order-accent); color: oklch(0.99 0.01 80); font-weight: 750; font-size: 15px; transition: background-color .2s, scale .2s var(--apr-order-spring); }
    & button:hover:not(:disabled) { background: color-mix(in oklch, var(--apr-order-accent) 88%, black); }
    & button:active:not(:disabled) { scale: .98; }
    & button:disabled { background: var(--apr-order-line2); color: var(--apr-order-mute); }
    & button span { font-family: var(--apr-order-mono); }
  }
  & .apr-order-form { display: grid; gap: 10px; padding-top: 4px;
    & label { display: grid; gap: 4px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apr-order-mute); }
    & input { height: 40px; padding: 0 12px; border-radius: 10px; border: 1px solid var(--apr-order-line2); background: var(--apr-order-bg); font-size: 14px; letter-spacing: 0; text-transform: none; color: var(--apr-order-ink); }
    & input:focus { outline: 2px solid var(--apr-order-accent); outline-offset: 0; border-color: transparent; }
    & input[aria-invalid="true"] { border-color: var(--apr-order-accent); background: color-mix(in oklch, var(--apr-order-accent) 6%, var(--apr-order-card)); }
    & .err { font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--apr-order-accent); }
    & .pay { display: grid; gap: 6px; }
    & .pay button { display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 10px; border: 1px solid var(--apr-order-line2); text-align: left; font-size: 13.5px; font-weight: 600; }
    & .pay button::before { content: ""; width: 16px; height: 16px; border-radius: 50%; border: 2px solid var(--apr-order-line2); flex: none; transition: border-width .2s var(--apr-order-spring), border-color .2s; }
    & .pay button[aria-checked="true"] { border-color: var(--apr-order-ink); background: var(--apr-order-bg); }
    & .pay button[aria-checked="true"]::before { border: 5px solid var(--apr-order-accent); }
    & .pay small { margin-left: auto; font-weight: 500; color: var(--apr-order-mute); font-size: 12px; }
    & .recap { margin: 2px 0 0; padding: 10px 12px; border-radius: 10px; background: var(--apr-order-tint); font-size: 13px; }
    & .recap b { font-family: var(--apr-order-mono); }
  }

  /* ── customise sheet ── */
  & .apr-order-scrim { position: absolute; inset: 0; z-index: 20; background: oklch(0.25 0.03 45 / .38); transition: opacity .25s; @starting-style { opacity: 0; } }
  & .apr-order-sheet { position: absolute; z-index: 21; left: 50%; top: 50%; translate: -50% -50%; width: min(460px, calc(100% - 24px)); max-height: calc(100% - 40px); display: flex; flex-direction: column; border-radius: 18px; background: var(--apr-order-card); box-shadow: 0 40px 80px -30px oklch(0.2 0.05 40 / .6); overflow: hidden;
    transition: opacity .2s, scale .4s var(--apr-order-spring); @starting-style { opacity: 0; scale: .94; }
    & .sh-hero { position: relative; display: grid; grid-template-columns: 1fr 112px; gap: 12px; padding: 18px 18px 14px; background: var(--apr-order-tint); }
    & .sh-hero h2 { font-size: 21px; font-weight: 800; letter-spacing: -.025em; }
    & .sh-hero p { margin: 4px 0 0; font-size: 13px; color: var(--apr-order-mute); }
    & .sh-hero .art > svg { width: 112px; height: 112px; stroke: none; }
