  /* ── order placed ── */
  & .apr-order-done { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: radial-gradient(120% 90% at 50% 0%, var(--apr-order-tint), var(--apr-order-bg) 70%); overflow-y: auto;
    transition: opacity .35s, translate .5s var(--apr-order-spring); @starting-style { opacity: 0; translate: 0 20px; }
