  let s = '<svg viewBox="0 0 100 100" aria-hidden="true"><defs><clipPath id="' + id + '"><circle cx="50" cy="50" r="' + inner + '"/></clipPath></defs>';
  s += '<circle cx="53" cy="55" r="45" fill="oklch(0.3 0.04 50 / .13)"/>';
  if (kind === 'glass') s += '<circle cx="50" cy="50" r="38" fill="oklch(0.97 0.01 220 / .7)" stroke="oklch(0.82 0.02 220)" stroke-width="2"/><circle cx="50" cy="50" r="33" fill="' + base + '"/>';
  else if (kind === 'cup') s += '<circle cx="50" cy="50" r="38" fill="' + vessel + '"/><circle cx="50" cy="50" r="34" fill="color-mix(in oklch, ' + vessel + ', black 8%)"/><circle cx="50" cy="50" r="30" fill="' + base + '"/>';
  else s += '<circle cx="50" cy="50" r="46" fill="' + vessel + '"/><circle cx="50" cy="50" r="' + (inner + 3) + '" fill="color-mix(in oklch, ' + vessel + ', black 10%)"/><circle cx="50" cy="50" r="' + inner + '" fill="' + base + '"/>';
  s += '<g clip-path="url(#' + id + ')">';
  if (kind === 'bowl') for (let i = 0; i < 9; i++) { const y = 26 + i * 6 + R() * 3, x = 14 + R() * 8; s += '<path d="M' + f(x) + ' ' + f(y) + 'q12 ' + f(-7 + R() * 14) + ' 24 0t24 0t24 0" fill="none" stroke="' + noodle + '" stroke-width="3.2" stroke-linecap="round" opacity=".92"/>'; }
  if (kind === 'rice') { s += '<circle cx="40" cy="44" r="20" fill="oklch(0.97 0.008 90)"/>'; for (let i = 0; i < 26; i++) { const a = R() * 6.28, d = R() * 17; s += '<ellipse cx="' + f(40 + Math.cos(a) * d) + '" cy="' + f(44 + Math.sin(a) * d) + '" rx="2" ry=".9" transform="rotate(' + f(R() * 180) + ' ' + f(40 + Math.cos(a) * d) + ' ' + f(44 + Math.sin(a) * d) + ')" fill="oklch(0.88 0.01 90)"/>'; } }
