      else if (t === 'ring') s += '<circle cx="' + f(x) + '" cy="' + f(y) + '" r="2.8" fill="none" stroke="' + c + '" stroke-width="1.6"/>';
      else if (t === 'dot') s += '<circle cx="' + f(x) + '" cy="' + f(y) + '" r="1" fill="' + c + '"/>';
      else if (t === 'puff') s += '<rect x="' + f(x - 4.5) + '" y="' + f(y - 4.5) + '" width="9" height="9" rx="3" fill="' + c + '" ' + T + '/>';
      else if (t === 'cube') s += '<rect x="' + f(x - 3.4) + '" y="' + f(y - 3.4) + '" width="6.8" height="6.8" rx="1.6" fill="' + c + '" ' + T + '/>';
