      else if (t === 'pod') s += '<path d="M' + f(x - 8) + ' ' + f(y) + 'c3-4 13-4 16 0-3 4-13 4-16 0Z" fill="' + c + '" ' + T + '/>';
      else if (t === 'cracker') s += '<circle cx="' + f(x) + '" cy="' + f(y) + '" r="7.5" fill="' + c + '" stroke="oklch(0.85 0.05 60)" stroke-width=".8"/>';
      else if (t === 'mango') s += '<rect x="' + f(x - 9) + '" y="' + f(y - 3) + '" width="18" height="6" rx="3" fill="' + c + '" ' + T + '/>';
      else if (t === 'dip') s += '<circle cx="62" cy="62" r="11" fill="oklch(0.97 0.01 90)" stroke="oklch(0.85 0.02 80)"/><circle cx="62" cy="62" r="8" fill="' + c + '"/>';
      else if (t === 'swirl') s += '<path d="M50 50m-14 0a14 14 0 1 0 28 0a10 10 0 1 0-20 0a6 6 0 1 0 12 0" fill="none" stroke="' + c + '" stroke-width="4" stroke-linecap="round"/>';
      else if (t === 'drizzle') s += '<path d="M30 40c8 6 14-6 22 0s14 6 20-2" fill="none" stroke="' + c + '" stroke-width="2.2" stroke-linecap="round"/>';
      else if (t === 'ice') s += '<rect x="' + f(x - 6) + '" y="' + f(y - 6) + '" width="12" height="12" rx="2.5" fill="' + c + '" opacity=".55" ' + T + '/>';
      else if (t === 'citrus') s += '<circle cx="' + f(x) + '" cy="' + f(y) + '" r="9" fill="' + c + '" stroke="oklch(0.96 0.03 100)" stroke-width="1.6"/><path d="M' + f(x - 9) + ' ' + f(y) + 'h18M' + f(x) + ' ' + f(y - 9) + 'v18" stroke="oklch(0.96 0.03 100)" stroke-width="1"/>';
    }
  });
