}

/* ── state ── */
const line = (item, qty, o) => Object.assign({ k: 'l' + Math.random().toString(36).slice(2, 7), item, qty, prot: (IT(item).prot || ''), spice: IT(item).spice || 0, add: [], size: 'reg', note: '' }, o || {});
let S = {
  lines: [line('n2', 1, { spice: 2 }), line('g2', 1), line('d1', 2)],
  avoid: [], q: '', slot: -1, tip: 0, stage: 'shop', pay: 'counter', name: '', phone: ''
};
const past = [];
const snap = () => { past.push(JSON.stringify(S)); if (past.length > 40) past.shift(); };
let sheet = null, order = null, fresh = null;

const now = new Date();
const t0 = (() => { const d = new Date(now.getTime() + 15 * MIN); d.setSeconds(0, 0); d.setMinutes(Math.ceil(d.getMinutes() / 15) * 15); return d.getTime(); })();
const BOOKED = [11, 12, 9, 7, 10, 4, 6, 3, 8, 5];
const slotT = i => t0 + i * 15 * MIN;
const hm = t => { const d = new Date(t); let h = d.getHours() % 12 || 12; return h + ':' + String(d.getMinutes()).padStart(2, '0'); };

const allergensOf = (it, o) => {
  const set = new Set(it.al);
  const p = PROTEIN.find(x => x[0] === (o ? o.prot : it.prot)); if (p && (it.opts || []).includes('protein')) p[3].forEach(a => set.add(a));
  (o ? o.add : []).forEach(k => ADDONS.find(x => x[0] === k)[3].forEach(a => set.add(a)));
