};
const unitPrice = (it, o) => it.p + ((it.opts || []).includes('protein') ? PROTEIN.find(x => x[0] === o.prot)[2] - PROTEIN.find(x => x[0] === it.prot)[2] : 0) + o.add.reduce((s, k) => s + ADDONS.find(x => x[0] === k)[2], 0) + (o.size === 'lg' ? 1 : 0);
