  }).join('') + '</div></fieldset>';
  if (o.includes('spice')) b += '<fieldset><legend>Heat <small>' + SPICE[sheet.spice] + '</small></legend><div class="spice" role="radiogroup" aria-label="Heat">' + SPICE.map((n, k) => '<button type="button" role="radio" data-spice="' + k + '" aria-checked="' + (sheet.spice === k) + '"><span>' + (k ? CHILI.repeat(k) : '&mdash;') + '</span>' + n + '</button>').join('') + '</div></fieldset>';
  if (o.includes('size')) b += '<fieldset><legend>Size</legend><div class="opts" role="radiogroup" aria-label="Size">' + SIZES.map(([k, n, d]) => '<button type="button" role="radio" class="opt" data-size="' + k + '" aria-checked="' + (sheet.size === k) + '"><span class="bx">' + svg('check') + '</span>' + n + '<span class="dp">' + (d ? '+' + usd(d) : '') + '</span></button>').join('') + '</div></fieldset>';
  if (o.includes('addons')) b += '<fieldset><legend>Add-ons <small>' + sheet.add.length + ' of 3</small></legend><div class="opts">' + ADDONS.map(([k, n, d, a]) => {
    const on = sheet.add.includes(k), no = a.some(x => S.avoid.includes(x)), full = !on && sheet.add.length >= 3;
    return '<button type="button" role="checkbox" class="opt" data-addon="' + k + '" aria-checked="' + on + '"' + (!on && (no || full) ? ' disabled title="' + (no ? 'Contains ' + a.map(x => AL[x].toLowerCase()).join(', ') : 'Pick up to 3 add-ons') + '"' : '') + '><span class="bx">' + svg('check') + '</span>' + n + (a.length ? ' <span class="al">' + a.map(x => AL[x]).join(', ') + '</span>' : '') + '<span class="dp">+' + usd(d) + '</span></button>';
  }).join('') + '</div></fieldset>';
  b += '<fieldset style="border:0"><legend>Note for the kitchen</legend><textarea data-note maxlength="80" placeholder="e.g. sauce on the side">' + esc(sheet.note) + '</textarea>' +
    '<p class="sh-alg' + (bad.length ? ' is-bad' : '') + '">' + (al.length ? 'Contains <b>' + al.map(a => AL[a].toLowerCase()).join(', ') + '</b>' : 'No listed allergens') + (bad.length ? ' · you asked us to avoid ' + bad.map(a => AL[a].toLowerCase()).join(', ') : '') + '</p></fieldset>';
  const price = r2(unitPrice(it, sheet) * sheet.qty);
  sheetEl.innerHTML = '<div class="sh-hero"><div><h2>' + esc(it.name) + '</h2><p>' + esc(it.ds) + '</p></div><div class="art">' + art(it) + '</div><button type="button" class="x" data-act="close-sheet" aria-label="Close">' + svg('x') + '</button></div>' +
    '<div class="sh-body">' + b + '</div>' +
    '<div class="sh-foot"><div class="stp" role="group" aria-label="Quantity"><button type="button" data-act="sq-dec"' + (sheet.qty <= 1 ? ' disabled title="At least one"' : '') + ' aria-label="One fewer">&minus;</button><output>' + sheet.qty + '</output><button type="button" data-act="sq-inc"' + (sheet.qty >= 9 ? ' disabled title="Nine is the most per line"' : '') + ' aria-label="One more">+</button></div>' +
    '<button type="button" class="go" data-act="sheet-add"' + (bad.length ? ' disabled title="Remove the choices that contain what you are avoiding"' : '') + '>' + (sheet.edit ? 'Update' : 'Add to bag') + '<span>' + usd(price) + '</span></button></div>';
  $('.sh-body', sheetEl).scrollTop = keep;
}

/* ── bag mutations ── */
function flyFrom(el) {
  if (RM.matches || !el) return;
  const target = getComputedStyle(bag).display !== 'none' ? $('.apr-order-baghead h2') : $('.apr-order-bagbar');
  if (!target) return;
  const rr = root.getBoundingClientRect(), a = el.getBoundingClientRect(), b = target.getBoundingClientRect();
  const f = root.ownerDocument.createElement('div'); f.className = 'apr-order-fly'; f.innerHTML = el.innerHTML; root.appendChild(f);
  const x0 = a.left - rr.left + a.width / 2 - 23, y0 = a.top - rr.top + a.height / 2 - 23, x1 = b.left - rr.left + 10, y1 = b.top - rr.top - 12;
  f.animate([
    { translate: x0 + 'px ' + y0 + 'px', scale: 1.6, opacity: 1 },
    { translate: (x0 + x1) / 2 + 'px ' + (Math.min(y0, y1) - 70) + 'px', scale: 1, opacity: 1, offset: .5 },
    { translate: x1 + 'px ' + y1 + 'px', scale: .35, opacity: .2 }
  ], { duration: 700, easing: 'cubic-bezier(.45,0,.2,1)' }).onfinish = () => f.remove();
}
function addLine(l, fromEl) {
  snap();
  const same = S.lines.find(x => x.item === l.item && x.prot === l.prot && x.spice === l.spice && x.size === l.size && x.note === l.note && x.add.join() === l.add.join());
  if (same) { same.qty = Math.min(9, same.qty + l.qty); fresh = same.k; } else { S.lines.push(l); fresh = l.k; }
  const before = chosenSlot();
  renderMenu(); renderBag(); flyFrom(fromEl);
  const after = chosenSlot();
  const msg = 'Added ' + l.qty + ' × ' + IT(l.item).name + (S.slot > -1 && !fits(S.slot) ? ' · pickup moved to ' + hm(slotT(after)) + ', ' + hm(slotT(S.slot)) + ' is full for this bag' : before !== after && after > -1 ? ' · earliest pickup is now ' + hm(slotT(after)) : '');
  toast(msg, true);
}
function undo() {
  if (!past.length) { toast('Nothing to undo'); return; }
  S = JSON.parse(past.pop()); render(); toast('Undone');
}

/* ── order placed ── */
const doneEl = $('.apr-order-done');
const STEPS = [['Received', 'check'], ['In the wok', 'wok'], ['Bagged', 'bag'], ['Ready', 'bell']];
function renderDone() {
  const T = order.T;
  doneEl.innerHTML = '<div class="card"><div class="no">Order ' + order.no + '</div><h2>Ready at <b>' + hm(order.at) + '</b>, ' + esc(order.name) + '</h2>' +
    '<p data-msg>We’ll text ' + esc(order.phone) + ' when it’s on the pickup shelf.</p>' +
    '<ol style="--apr-order-fill:0">' + STEPS.map(([n, ic], i) => '<li data-s="' + i + '"><i>' + svg(ic) + '</i>' + n + '</li>').join('') + '</ol>' +
    '<div class="rcpt">' + order.lines.map(l => '<div><span>' + l.qty + ' × ' + esc(IT(l.item).name) + '</span><span>' + usd(linePrice(l)) + '</span></div>').join('') +
    '<div><span>Subtotal</span><span>' + usd(T.sub) + '</span></div><div><span>Tax 8.25%</span><span>' + usd(T.tax) + '</span></div>' + (T.tip ? '<div><span>Tip</span><span>' + usd(T.tip) + '</span></div>' : '') +
    '<div class="t"><span>' + (order.pay === 'card' ? 'Charged to •••• 4821' : 'Pay at pickup') + '</span><span>' + usd(T.total) + '</span></div></div>' +
    '<div class="btns"><button type="button" data-act="again">Order the same again</button><button type="button" class="is-primary" data-act="new">Start a new order</button></div></div>';
  doneEl.hidden = false;
  setStep(0);
}
function setStep(n) {
  if (!order) return;
  order.step = n;
  const ol = $('ol', doneEl); if (!ol) return;
  ol.style.setProperty('--apr-order-fill', (n / 3).toFixed(3));
  $$('li', ol).forEach((li, i) => { li.classList.toggle('is-on', i <= n); li.classList.toggle('is-now', i === n); });
  if (n === 3) $('[data-msg]', doneEl).textContent = 'On the pickup shelf, cubby ' + (3 + (order.no.charCodeAt(4) % 9)) + '. Say “' + order.name + '” at the counter.';
}
function place() {
  const fm = $('.apr-order-form', bag); if (!fm) return;
  const name = fm.elements.name.value.trim(), phone = fm.elements.phone.value.trim(), digits = phone.replace(/\D/g, '');
  S.name = name; S.phone = phone;
  let ok = true;
  const err = (k, m) => { const i = fm.elements[k]; i.setAttribute('aria-invalid', m ? 'true' : 'false'); $('[data-err="' + k + '"]', fm).textContent = m; if (m && ok) { i.focus(); ok = false; } };
  err('name', name ? '' : 'Add a name so the counter can find your bag.');
  err('phone', digits.length >= 10 ? '' : 'Enter a 10-digit mobile number for the ready text.');
  if (!ok) { toast('Check the highlighted fields'); return; }
  const ch = chosenSlot();
  order = { no: 'M-' + (2400 + Math.floor(Math.random() * 90)), at: slotT(ch), name, phone: '••• ' + digits.slice(-4), pay: S.pay, lines: JSON.parse(JSON.stringify(S.lines)), T: totals(), step: 0, t: Date.now() };
  BOOKED[ch] += units();
  S.stage = 'placed';
  renderDone();
}

/* ── events ── */
const search = $('.apr-order-search input');
search.addEventListener('input', () => { S.q = search.value; renderMenu(); menu.scrollTop = 0; });
root.addEventListener('input', e => { if (e.target.matches('[data-note]') && sheet) sheet.note = e.target.value.slice(0, 80); });
root.addEventListener('submit', e => { e.preventDefault(); place(); });
root.addEventListener('click', e => {
  const t = e.target;
  const avoidB = t.closest('[data-avoid]');
  if (avoidB) { const k = avoidB.dataset.avoid; S.avoid = S.avoid.includes(k) ? S.avoid.filter(x => x !== k) : S.avoid.concat(k); renderAvoid(); renderMenu(); toast(S.avoid.length ? 'Hiding dishes with ' + S.avoid.map(a => AL[a].toLowerCase()).join(', ') : 'Showing every dish'); return; }
  if (t === scrim) { closeSheet(); return; }
  const cat = t.closest('.apr-order-cats [data-cat]');
  if (cat) { curCat = cat.dataset.cat; $$('.apr-order-cats [data-cat]').forEach(b => b.setAttribute('aria-current', b === cat)); const sec = $('.apr-order-sec[data-cat="' + curCat + '"]', menu); if (sec) menu.scrollTo({ top: sec.offsetTop - 4, behavior: RM.matches ? 'auto' : 'smooth' }); return; }
  const sl = t.closest('[data-slot]'); if (sl) { snap(); S.slot = +sl.dataset.slot; renderBag(); return; }
  const tp = t.closest('[data-tip]'); if (tp) { snap(); S.tip = +tp.dataset.tip; renderBag(); return; }
  const py = t.closest('[data-pay]'); if (py) { const fm = $('.apr-order-form', bag); if (fm) { S.name = fm.elements.name.value; S.phone = fm.elements.phone.value; } S.pay = py.dataset.pay; renderBag(); return; }
  if (sheet) {
    const pr = t.closest('[data-prot]'); if (pr) { sheet.prot = pr.dataset.prot; renderSheet(); return; }
    const sp = t.closest('[data-spice]'); if (sp) { sheet.spice = +sp.dataset.spice; renderSheet(); return; }
    const sz = t.closest('[data-size]'); if (sz) { sheet.size = sz.dataset.size; renderSheet(); return; }
    const ad = t.closest('[data-addon]'); if (ad) { const k = ad.dataset.addon; sheet.add = sheet.add.includes(k) ? sheet.add.filter(x => x !== k) : ADDONS.map(x => x[0]).filter(x => x === k || sheet.add.includes(x)); renderSheet(); return; }
  }
  const a = t.closest('[data-act]'); if (!a) return;
  const act = a.dataset.act, li = a.closest('.apr-order-line'), L = li && S.lines.find(l => l.k === li.dataset.k), card = a.closest('.apr-order-item');
  if (act === 'undo') undo();
  else if (act === 'avoid') toggleAvoidPanel();
  else if (act === 'add') { const it = IT(card.dataset.id); if (it.opts) openSheet(it.id); else addLine(line(it.id, 1), $('.art', card)); }
  else if (act === 'close-sheet') closeSheet();
  else if (act === 'sq-dec') { sheet.qty = Math.max(1, sheet.qty - 1); renderSheet(); }
  else if (act === 'sq-inc') { sheet.qty = Math.min(9, sheet.qty + 1); renderSheet(); }
  else if (act === 'sheet-add') {
    const s = sheet, artEl = $('.sh-hero .art', sheetEl).cloneNode(true);
    closeSheet();
    if (s.edit) { snap(); const l = S.lines.find(x => x.k === s.edit); Object.assign(l, { qty: s.qty, prot: s.prot, spice: s.spice, add: s.add, size: s.size, note: s.note }); fresh = l.k; renderMenu(); renderBag(); toast('Updated ' + IT(l.item).name, true); }
    else { const c = $('.apr-order-item[data-id="' + s.item + '"] .art', menu); addLine(line(s.item, s.qty, { prot: s.prot, spice: s.spice, add: s.add, size: s.size, note: s.note }), c || artEl); }
  }
  else if (act === 'inc' && L) { snap(); L.qty = Math.min(9, L.qty + 1); renderMenu(); renderBag(); }
  else if (act === 'dec' && L) { snap(); if (L.qty > 1) L.qty--; else S.lines = S.lines.filter(x => x !== L); renderMenu(); renderBag(); if (!S.lines.includes(L)) toast('Removed ' + IT(L.item).name, true); }
  else if (act === 'rm' && L) { snap(); S.lines = S.lines.filter(x => x !== L); renderMenu(); renderBag(); toast('Removed ' + IT(L.item).name, true); }
  else if (act === 'edit' && L) openSheet(L.item, L.k);
  else if (act === 'clear-bag') { snap(); S.lines = []; renderMenu(); renderBag(); toast('Bag cleared', true); }
  else if (act === 'clear-q') { S.q = ''; search.value = ''; renderMenu(); }
  else if (act === 'checkout') { S.stage = 'checkout'; renderBag(); root.dataset.view = 'bag'; const n = $('.apr-order-form input', bag); if (n) n.focus({ preventScroll: true }); }
  else if (act === 'back-bag') { const fm = $('.apr-order-form', bag); if (fm) { S.name = fm.elements.name.value; S.phone = fm.elements.phone.value; } S.stage = 'shop'; renderBag(); }
  else if (act === 'place') place();
  else if (act === 'view-bag') { root.dataset.view = 'bag'; renderBag(); }
  else if (act === 'view-menu') { root.dataset.view = 'menu'; }
  else if (act === 'again' || act === 'new') {
    doneEl.hidden = true; const prev = order; order = null;
    S = { lines: act === 'again' ? prev.lines.map(l => Object.assign({}, l, { k: 'l' + Math.random().toString(36).slice(2, 7) })) : [], avoid: S.avoid, q: '', slot: -1, tip: S.tip, stage: 'shop', pay: S.pay, name: S.name, phone: S.phone };
    past.length = 0; root.dataset.view = 'menu'; render(); menu.scrollTop = 0;
    toast(act === 'again' ? 'Bag refilled from ' + prev.no + ' · pick a new pickup time' : 'New order started');
  }
});
root.addEventListener('keydown', e => {
  const t = e.target, typing = t.matches('input, textarea');
  if (e.key === 'Escape') {
    if (sheet) { closeSheet(); return; }
    if (!$('.apr-order-avoid').hidden) { toggleAvoidPanel(false); $('.apr-order-avoidbtn').focus(); return; }
    if (typing && t === search && search.value) { search.value = ''; S.q = ''; renderMenu(); return; }
    if (S.stage === 'checkout') { const fm = $('.apr-order-form', bag); if (fm) { S.name = fm.elements.name.value; S.phone = fm.elements.phone.value; } S.stage = 'shop'; renderBag(); return; }
    return;
  }
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z' && !typing) { e.preventDefault(); undo(); return; }
  if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === '/') { e.preventDefault(); search.focus(); return; }
  const r = t.closest('[role="radiogroup"]');
  if (r && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const opts = $$('[role="radio"]:not(:disabled)', r), i = opts.indexOf(t.closest('[role="radio"]')), d = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;
    const n = opts[(i + d + opts.length) % opts.length]; if (!n) return;
    const key = Object.keys(n.dataset)[0], val = n.dataset[key];
    n.click();
    const m = root.querySelector('[data-' + key + '="' + val + '"]'); if (m) m.focus({ preventScroll: true });
  }
});

/* ── the kitchen moves the order along while the confirmation is on screen ── */
let onScreen = true;
const io = new IntersectionObserver(es => { onScreen = es[es.length - 1].isIntersecting; });
io.observe(root);
const timer = setInterval(() => {
  if (!root.isConnected) { clearInterval(timer); io.disconnect(); if (spyIO) spyIO.disconnect(); return; }
  if (!onScreen || document.hidden || !order || order.step >= 3) return;
  if (Date.now() - order.t > (order.step + 1) * 3200) setStep(order.step + 1);
}, 400);

render();

css:
.apr-book {
  --apr-book-bg: oklch(0.972 0.014 88);
  --apr-book-ink: oklch(0.24 0.02 30);
  --apr-book-accent: oklch(0.46 0.14 20);
  --apr-book-moss: oklch(0.55 0.09 140);
  --apr-book-gold: oklch(0.78 0.12 80);
  --apr-book-card: color-mix(in oklch, var(--apr-book-bg), white 70%);
  --apr-book-line: color-mix(in oklch, var(--apr-book-ink) 10%, transparent);
  --apr-book-line2: color-mix(in oklch, var(--apr-book-ink) 20%, transparent);
  --apr-book-mute: color-mix(in oklch, var(--apr-book-ink) 56%, var(--apr-book-bg));
  --apr-book-tint: color-mix(in oklch, var(--apr-book-accent) 9%, var(--apr-book-card));
  --apr-book-lab: 104px;
  --apr-book-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-book-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-book-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --apr-book-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-book-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-book;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apr-book-line);
  background: var(--apr-book-bg); color: var(--apr-book-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--apr-book-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .45; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apr-book-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--apr-book-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apr-book-line2); border-bottom-width: 2px; color: var(--apr-book-mute); background: var(--apr-book-card); }

  & .apr-book-app { height: 100%; display: grid; grid-template: "top top" auto "main panel" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) 300px; }

  /* ── header ── */
  & .apr-book-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 10px 16px; border-bottom: 1px solid var(--apr-book-line); background: var(--apr-book-card); }
  & .apr-book-brand { display: grid; line-height: 1.05; flex: none;
    & b { font: italic 600 21px/1 var(--apr-book-serif); letter-spacing: -.01em; color: var(--apr-book-accent); }
    & span { font-size: 10.5px; font-weight: 700; letter-spacing: .16em; text-transform: uppercase; color: var(--apr-book-mute); margin-top: 3px; }
  }
  & .apr-book-date { display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 10px; border: 1px solid var(--apr-book-line2); margin-left: 8px;
    & > button:not(.apr-book-today) { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 7px; }
    & > button:hover { background: var(--apr-book-bg); }
    & svg { width: 16px; height: 16px; }
  }
  & .apr-book-today { display: grid; justify-items: center; min-width: 108px; padding: 2px 8px; border-radius: 7px; line-height: 1.1;
    & b { font: 600 14.5px var(--apr-book-serif); }
    & small { font-size: 10.5px; color: var(--apr-book-mute); font-weight: 600; letter-spacing: .04em; }
  }
  & .apr-book-svc { display: flex; padding: 3px; border-radius: 10px; background: var(--apr-book-bg); border: 1px solid var(--apr-book-line);
    & button { height: 30px; padding: 0 12px; border-radius: 7px; font-size: 13px; font-weight: 600; color: var(--apr-book-mute); }
    & button[aria-selected="true"] { background: var(--apr-book-ink); color: var(--apr-book-bg); }
  }
  & .apr-book-search { margin-left: auto; display: flex; align-items: center; gap: 8px; height: 36px; width: min(230px, 24cqi); padding: 0 8px 0 11px; border-radius: 10px; background: var(--apr-book-bg); border: 1px solid var(--apr-book-line);
    & svg { width: 16px; height: 16px; color: var(--apr-book-mute); flex: none; }
    & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 13.5px; }
    &:focus-within { border-color: var(--apr-book-ink); }
  }
  & .apr-book-new { display: flex; align-items: center; gap: 6px; height: 36px; padding: 0 14px 0 10px; border-radius: 10px; background: var(--apr-book-accent); color: oklch(0.98 0.01 80); font-size: 13px; font-weight: 650; white-space: nowrap;
    & svg { width: 16px; height: 16px; stroke-width: 2.2; }
    &:hover { background: color-mix(in oklch, var(--apr-book-accent) 85%, black); }
  }
  & .apr-book-views { grid-area: views; display: none; gap: 4px; padding: 8px 12px; border-bottom: 1px solid var(--apr-book-line); background: var(--apr-book-card);
    & button { flex: 1; height: 34px; border-radius: 8px; font-weight: 600; font-size: 13px; color: var(--apr-book-mute); }
    & button[aria-selected="true"] { background: var(--apr-book-ink); color: var(--apr-book-bg); }
  }

  /* ── the sheet: pacing, axis and every table row share one column grid through subgrid ── */
  & .apr-book-main { grid-area: main; min-height: 0; overflow: auto; position: relative; scrollbar-width: thin; }
  & .apr-book-sheet { display: grid; grid-template-columns: var(--apr-book-lab) minmax(0, 1fr); min-width: 560px; padding: 0 14px 18px 0; user-select: none; -webkit-user-select: none; }
  & .apr-book-pace, & .apr-book-axis, & .apr-book-row, & .apr-book-area { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  & .apr-book-pace { position: sticky; top: 0; z-index: 6; padding-top: 12px; background: var(--apr-book-bg);
    & .lab { padding: 0 10px 0 16px; align-self: end; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apr-book-mute); line-height: 1.3; padding-bottom: 4px; }
