    &[data-view="grid"] .apr-book-panel, &[data-view="panel"] .apr-book-main { display: none; }
    & .apr-book-sheet { min-width: 0; padding-right: 12px; }
    & .apr-book-axis, & .apr-book-rows { display: none; }
    & .apr-book-pace { position: static; }
    & .apr-book-agenda { display: block; }
    & .apr-book-panel .back { display: inline-flex; }
    & .apr-book-top { flex-wrap: wrap; gap: 8px; padding: 10px 12px; }
    & .apr-book-date { margin-left: 0; order: 4; }
    & .apr-book-svc { order: 5; margin-left: auto; }
    & .apr-book-new { margin-left: auto; }
