    & .apr-book-pace .bar span { display: none; }
  }
  @container apr-book (max-width: 440px) {
    & .apr-book-app { --apr-book-lab: 72px; }
    & .apr-book-pace .lab { padding-left: 12px; font-size: 9.5px; }
    & .apr-book-today { min-width: 86px; }
  }

  @media (prefers-reduced-motion: reduce) {
    & .apr-book-bk { animation: none; transition: opacity .2s; }
    & .apr-book-pace .bar { transition: none; }
    & .apr-book-panel > * { animation: none; }
    & .apr-book-toast { transition: opacity .2s; }
  }
}

@keyframes apr-book-in { from { opacity: 0; clip-path: inset(0 100% 0 0 round 7px); } }
@keyframes apr-book-fade { from { opacity: 0; translate: 0 6px; } }

