/* ── Wrenfield Room reservations. Pacing bars, the time axis and every table row share one column grid
   (subgrid), so a booking dragged along its row lines up with the covers it adds. While you drag,
   the pacing chart is recomputed from the moved booking: you see the 19:00 rush form or clear. ── */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const hm = m => Math.floor(m / 60) + ':' + String(m % 60).padStart(2, '0');
const IC = {
  cake: '<path d="M5 20v-7h14v7M4 20h16M7 13v-2h10v2M12 11V8"/><path d="M12 5.5c.8 0 1.2-.6 1-1.4L12 2.5l-1 1.6c-.2.8.2 1.4 1 1.4Z"/>',
  ring: '<circle cx="12" cy="14" r="6"/><path d="m9.5 4 2.5 3 2.5-3"/>', alert: '<path d="M12 4 2.8 20h18.4L12 4Z"/><path d="M12 10v4.2M12 17.2v.3"/>',
  star: '<path d="m12 4 2.4 4.9 5.4.8-3.9 3.8.9 5.4L12 16.4l-4.8 2.5.9-5.4-3.9-3.8 5.4-.8L12 4Z"/>', win: '<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M12 4v16M4 12h16"/>',
  msg: '<path d="M5 5h14v10H9l-4 4V5Z"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>', back: '<path d="M15 5 8 12l7 7"/>', chair: '<path d="M7 4v9h10M7 13l-1 7M17 13l1 7M7 9h7"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const TAGS = [['birthday', 'Birthday', 'cake'], ['anniv', 'Anniversary', 'ring'], ['allergy', 'Allergy', 'alert'], ['vip', 'Regular', 'star'], ['window', 'Window', 'win']];
const ST = [['booked', 'Booked'], ['confirmed', 'Confirmed'], ['arrived', 'Arrived'], ['seated', 'Seated'], ['done', 'Done']];
const STN = { booked: 'Booked', confirmed: 'Confirmed', arrived: 'Arrived', seated: 'Seated', done: 'Finished', noshow: 'No-show' };
const SV = { lunch: [690, 900], dinner: [1020, 1380] };
const TABLES = [['W1', 2, 'Window'], ['W2', 2, 'Window'], ['W3', 2, 'Window'], ['W4', 4, 'Window'], ['T5', 4, 'Main room'], ['T6', 4, 'Main room'], ['T7', 4, 'Main room'], ['T8', 6, 'Main room'], ['B9', 4, 'Booths'], ['B10', 4, 'Booths'], ['B11', 6, 'Booths'], ['P12', 10, 'Private room']];
