css:
.apr-cost {
  --apr-cost-bg: oklch(0.966 0.012 115);
  --apr-cost-ink: oklch(0.27 0.035 160);
  --apr-cost-accent: oklch(0.62 0.14 55);
  --apr-cost-good: oklch(0.56 0.12 150);
  --apr-cost-warn: oklch(0.7 0.14 75);
  --apr-cost-bad: oklch(0.55 0.17 30);
  --apr-cost-card: color-mix(in oklch, var(--apr-cost-bg), white 72%);
  --apr-cost-line: color-mix(in oklch, var(--apr-cost-ink) 10%, transparent);
  --apr-cost-line2: color-mix(in oklch, var(--apr-cost-ink) 20%, transparent);
  --apr-cost-mute: color-mix(in oklch, var(--apr-cost-ink) 56%, var(--apr-cost-bg));
  --apr-cost-tint: color-mix(in oklch, var(--apr-cost-accent) 11%, var(--apr-cost-card));
  --apr-cost-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-cost-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-cost-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-cost-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-cost;
