  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { text-wrap: pretty; }
  & .num { font-family: var(--apr-cost-mono); font-variant-numeric: tabular-nums; }
  & .eyebrow { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apr-cost-mute); }
  & kbd { font: 600 10px/1 var(--apr-cost-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apr-cost-line2); border-bottom-width: 2px; color: var(--apr-cost-mute); background: var(--apr-cost-card); }
  & .fc { display: inline-flex; align-items: center; height: 22px; padding: 0 7px; border-radius: 6px; font: 700 11.5px var(--apr-cost-mono); font-variant-numeric: tabular-nums; color: var(--fc); background: color-mix(in oklch, var(--fc) 13%, var(--apr-cost-card)); --fc: var(--apr-cost-good); }
  & .fc[data-r="warn"] { --fc: color-mix(in oklch, var(--apr-cost-warn) 70%, var(--apr-cost-ink)); }
  & .fc[data-r="bad"] { --fc: var(--apr-cost-bad); }

  & .apr-cost-app { height: 100%; display: grid; grid-template: "top top top" auto "list sheet price" minmax(0, 1fr) "keys keys keys" auto / 236px minmax(0, 1fr) 312px; }

