/* ── Cinder & Salt recipe costing. Every cost is computed from purchase price ÷ yield × portion, and
   prep recipes are ingredients too, so editing the jus re-prices every dish that ladles it. The
   composition bar is the table drawn: one flex segment per row, flex-grow = its cents. ── */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = n => (n < 0 ? '−$' : '$') + Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const usdU = n => n < 1 ? '$' + n.toFixed(3) : usd(n);
const pct = n => (n * 100).toFixed(1) + '%';
const IC = { x: '<path d="M6 6l12 12M18 6 6 18"/>', plus: '<path d="M12 5v14M5 12h14"/>', check: '<path d="m5 12.5 4.5 4.5L19 7"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const CAT = { protein: ['Protein', 'oklch(0.56 0.13 32)'], produce: ['Produce', 'oklch(0.64 0.13 140)'], dairy: ['Dairy', 'oklch(0.83 0.08 92)'], pantry: ['Pantry', 'oklch(0.72 0.1 70)'], liquor: ['Wine', 'oklch(0.46 0.12 350)'], prep: ['Prep', 'oklch(0.52 0.07 235)'], q: ['Q-factor', 'oklch(0.78 0.02 120)'] };
/* name, category, price, purchase unit, base unit, base units per purchase unit, usual yield % */
const PANTRY = {
  shortrib: ['Beef short rib, bone-in', 'protein', 8.40, 'lb', 'g', 453.6, 55], octopus: ['Octopus, Spanish', 'protein', 14.20, 'lb', 'g', 453.6, 50],
  burrata: ['Burrata, 4 oz', 'dairy', 3.85, 'ea', 'ea', 1, 100], rice: ['Carnaroli rice', 'pantry', 3.10, 'lb', 'g', 453.6, 100],
  maitake: ['Maitake mushrooms', 'produce', 12.00, 'lb', 'g', 453.6, 85], butter: ['Butter, unsalted', 'dairy', 4.60, 'lb', 'g', 453.6, 100],
  parm: ['Parmigiano, 24 month', 'dairy', 15.80, 'lb', 'g', 453.6, 92], potato: ['Yukon gold potatoes', 'produce', 0.95, 'lb', 'g', 453.6, 82],
  cream: ['Heavy cream', 'dairy', 5.20, 'qt', 'ml', 946, 100], carrot: ['Heirloom carrots', 'produce', 1.80, 'lb', 'g', 453.6, 78],
  lemon: ['Lemons', 'produce', 0.45, 'ea', 'ea', 1, 100], oil: ['Olive oil, arbequina', 'pantry', 38.00, '3 L', 'ml', 3000, 100],
  tomato: ['Heirloom tomatoes', 'produce', 3.60, 'lb', 'g', 453.6, 88], peach: ['Peaches', 'produce', 2.40, 'lb', 'g', 453.6, 85],
  basil: ['Basil', 'produce', 14.00, 'lb', 'g', 453.6, 60], bread: ['Sourdough, sliced', 'pantry', 0.28, 'slice', 'ea', 1, 100],
  egg: ['Eggs, pasture', 'dairy', 0.42, 'ea', 'ea', 1, 100], wine: ['Red wine, cooking', 'liquor', 7.50, '750 ml', 'ml', 750, 100],
  stock: ['Veal stock', 'pantry', 6.40, 'qt', 'ml', 946, 100], shallot: ['Shallots', 'produce', 2.90, 'lb', 'g', 453.6, 85],
  chili: ['Calabrian chili', 'pantry', 12.00, 'lb', 'g', 453.6, 100], sugar: ['Sugar', 'pantry', 0.85, 'lb', 'g', 453.6, 100],
  choc: ['Dark chocolate 70%', 'pantry', 9.50, 'lb', 'g', 453.6, 100], herbs: ['Parsley & chives', 'produce', 9.00, 'lb', 'g', 453.6, 70],
  salt: ['Flaky salt', 'pantry', 11.00, 'lb', 'g', 453.6, 100], hazelnut: ['Hazelnuts, toasted', 'pantry', 13.50, 'lb', 'g', 453.6, 100],
  creme: ['Crème fraîche', 'dairy', 6.80, 'lb', 'g', 453.6, 100]
};
let rk = 0;
const row = (item, qty, y) => ({ k: 'r' + (++rk), item, qty, y: y || (PANTRY[item] ? PANTRY[item][6] : 100) });
let S = {
  sel: 'rib', target: 30, round: 'whole', sort: false, prices: {}, whatif: 0,
  recipes: [
    { id: 'rib', kind: 'dish', name: 'Braised short rib', sub: 'Potato purée, glazed carrots, red wine jus', course: 'Main', price: 34, q: 3, sold: 142, rows: [row('shortrib', 220), row('potato', 150), row('butter', 30), row('cream', 40), row('jus', 90), row('carrot', 80), row('herbs', 5)] },
    { id: 'octo', kind: 'dish', name: 'Charred octopus', sub: 'Crushed potato, Calabrian chili, herb oil', course: 'Main', price: 29, q: 3, sold: 96, rows: [row('octopus', 140), row('potato', 100), row('chili', 10), row('lemon', 0.5), row('oil', 20), row('hoil', 15)] },
    { id: 'burr', kind: 'dish', name: 'Burrata & late peaches', sub: 'Heirloom tomato, basil, grilled sourdough', course: 'Starter', price: 19, q: 3, sold: 118, rows: [row('burrata', 1), row('peach', 120), row('tomato', 80), row('basil', 4), row('oil', 15), row('bread', 2)] },
    { id: 'riso', kind: 'dish', name: 'Maitake risotto', sub: 'Carnaroli, aged parmigiano, brown butter', course: 'Main', price: 27, q: 3, sold: 131, rows: [row('rice', 90), row('maitake', 120), row('parm', 25), row('butter', 25), row('stock', 250), row('shallot', 20), row('wine', 40), row('herbs', 3)] },
    { id: 'pot', kind: 'dish', name: 'Chocolate pot de crème', sub: 'Crème fraîche, toasted hazelnut, flaky salt', course: 'Dessert', price: 12, q: 3, sold: 88, rows: [row('choc', 50), row('cream', 100), row('egg', 1.5), row('sugar', 20), row('creme', 20), row('hazelnut', 8), row('salt', 0.5)] },
    { id: 'jus', kind: 'prep', name: 'Red wine jus', sub: 'Reduced three to one, mounted with butter', yieldQ: 1000, unit: 'ml', rows: [row('stock', 2000), row('wine', 750), row('shallot', 200), row('butter', 60)] },
    { id: 'hoil', kind: 'prep', name: 'Herb oil', sub: 'Blanched, blitzed, hung overnight', yieldQ: 450, unit: 'ml', rows: [row('oil', 500), row('herbs', 120)] }
  ]
};
const past = [];
const snap = () => { past.push(JSON.stringify(S)); if (past.length > 50) past.shift(); };
const REC = id => S.recipes.find(r => r.id === id);
const sel = () => REC(S.sel);

/* ── the arithmetic ── */
const priceOf = (id, ov) => (ov && ov[id] != null ? ov[id] : S.prices[id] != null ? S.prices[id] : PANTRY[id][2]);
const isPrep = id => !PANTRY[id];
const baseUnit = id => isPrep(id) ? REC(id).unit : PANTRY[id][4];
const unitCost = (id, ov, depth) => isPrep(id) ? batchCost(REC(id), ov, (depth || 0) + 1) / REC(id).yieldQ : priceOf(id, ov) / PANTRY[id][5];
const rowCost = (r, ov, depth) => unitCost(r.item, ov, depth) * r.qty / ((isPrep(r.item) ? 100 : r.y) / 100);
const batchCost = (rec, ov, depth) => (depth || 0) > 4 ? 0 : rec.rows.reduce((s, r) => s + rowCost(r, ov, depth), 0);
const qCost = (rec, ov) => rec.kind === 'dish' ? batchCost(rec, ov) * rec.q / 100 : 0;
const plateCost = (rec, ov) => batchCost(rec, ov) + qCost(rec, ov);
const fcOf = (rec, ov) => rec.kind === 'dish' && rec.price > 0 ? plateCost(rec, ov) / rec.price : 0;
const rating = fc => fc <= S.target / 100 ? 'good' : fc <= S.target / 100 + 0.03 ? 'warn' : 'bad';
function suggest(cost) {
  const v = cost / (S.target / 100);
  return S.round === 'half' ? Math.ceil(v * 2) / 2 : S.round === 'charm' ? Math.ceil(v + 0.05) - 0.05 : Math.ceil(v);
}
const usesOf = id => S.recipes.filter(r => r.rows.some(x => x.item === id));
const nameOf = id => isPrep(id) ? REC(id).name : PANTRY[id][0];
const catOf = id => isPrep(id) ? 'prep' : PANTRY[id][1];
const fmtQty = (q, u) => (Math.round(q * 10) / 10) + ' ' + u;
const perLabel = id => isPrep(id) ? usdU(unitCost(id)) + '/' + REC(id).unit : usd(priceOf(id)) + '/' + PANTRY[id][3];
function theoretical() {
  const d = S.recipes.filter(r => r.kind === 'dish');
  const c = d.reduce((s, r) => s + plateCost(r) * r.sold, 0), p = d.reduce((s, r) => s + r.price * r.sold, 0);
  return { fc: c / p, over: d.filter(r => rating(fcOf(r)) === 'bad').length, n: d.length };
}

/* ── toast + number tween ── */
const toastEl = $('.apr-cost-toast');
let toastT = 0;
function toast(msg, undoable) {
  $('[data-msg]', toastEl).textContent = msg;
  toastEl.classList.toggle('has-undo', !!undoable);
  toastEl.classList.add('is-on');
  clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 3600);
}
const tweens = new WeakMap();
function tween(el, to, fmt) {
  if (!el) return;
  const from = parseFloat(el.dataset.n || to);
  el.dataset.n = to;
  if (RM.matches || Math.abs(from - to) < 0.005) { el.textContent = fmt(to); return; }
  const t0 = performance.now(), id = {};
  tweens.set(el, id);
  const step = now => {
    if (!root.isConnected) return;
    if (tweens.get(el) !== id) return;
    const k = Math.min(1, (now - t0) / 520), e = 1 - Math.pow(1 - k, 4);
    el.textContent = fmt(from + (to - from) * e);
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* ── list ── */
function renderList() {
  let dishes = S.recipes.filter(r => r.kind === 'dish');
  if (S.sort) dishes = dishes.slice().sort((a, b) => fcOf(b) - fcOf(a));
  const preps = S.recipes.filter(r => r.kind === 'prep');
  const li = r => {
    const fc = fcOf(r);
