  if (t.matches('[data-whatif]')) { S.whatif = +t.value; whatifText(); return; }
  if (pick && t === $('input', pick)) { fillPick(t.value); return; }
  const r = sel(), v = parseFloat(t.value), lab = t.closest('.fld, .money');
  const okNum = !isNaN(v) && v >= 0;
  if (!t.matches('[data-q],[data-y],[data-qf],[data-price],[data-batch]')) return;
  if (!okNum || (t.matches('[data-y]') && (v < 1 || v > 100)) || (t.matches('[data-price],[data-batch]') && v <= 0)) { if (lab) lab.setAttribute('data-bad', ''); return; }
  if (lab) lab.removeAttribute('data-bad');
  if (!editing) { snap(); editing = true; }
  if (t.dataset.q) r.rows.find(x => x.k === t.dataset.q).qty = v;
  else if (t.dataset.y) r.rows.find(x => x.k === t.dataset.y).y = v;
  else if (t.matches('[data-qf]')) r.q = v;
