    e.preventDefault();
    const ids = $$('.apr-cost-rec').map(x => x.dataset.r), i = ids.indexOf(S.sel), n = ids[Math.max(0, Math.min(ids.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))];
    select(n, true);
  }
});

renderAll();

css:
@property --apr-cashup-hold { syntax: "<number>"; inherits: true; initial-value: 0; }

.apr-cashup {
  --apr-cashup-bg: oklch(0.2 0.028 165);
  --apr-cashup-ink: oklch(0.95 0.015 95);
  --apr-cashup-accent: oklch(0.8 0.12 85);
  --apr-cashup-good: oklch(0.78 0.13 160);
  --apr-cashup-warn: oklch(0.82 0.14 80);
  --apr-cashup-bad: oklch(0.7 0.16 30);
  --apr-cashup-panel: color-mix(in oklch, var(--apr-cashup-bg), black 18%);
  --apr-cashup-card: color-mix(in oklch, var(--apr-cashup-bg), var(--apr-cashup-ink) 6%);
  --apr-cashup-line: color-mix(in oklch, var(--apr-cashup-ink) 11%, transparent);
  --apr-cashup-line2: color-mix(in oklch, var(--apr-cashup-ink) 22%, transparent);
  --apr-cashup-mute: color-mix(in oklch, var(--apr-cashup-ink) 58%, var(--apr-cashup-bg));
  --apr-cashup-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-cashup-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-cashup-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--apr-cashup-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apr-cashup;
  overflow: clip; isolation: isolate; border-radius: 14px;
  background: radial-gradient(120% 80% at 30% 0%, color-mix(in oklch, var(--apr-cashup-bg), var(--apr-cashup-good) 7%), var(--apr-cashup-bg) 60%);
  color: var(--apr-cashup-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apr-cashup-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apr-cashup-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { text-wrap: pretty; }
  & .num { font-family: var(--apr-cashup-mono); font-variant-numeric: tabular-nums; }
  & .eyebrow { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apr-cashup-mute); }
  & kbd { font: 600 10px/1 var(--apr-cashup-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apr-cashup-line2); border-bottom-width: 2px; color: var(--apr-cashup-mute); }
  & .var { font-family: var(--apr-cashup-mono); font-weight: 750; color: var(--v, var(--apr-cashup-good)); }
  & .var[data-r="warn"] { --v: var(--apr-cashup-warn); } & .var[data-r="bad"] { --v: var(--apr-cashup-bad); }

  & .apr-cashup-app { height: 100%; display: grid; grid-template: "top top" auto "main ledger" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) 316px; }

  /* ── header + stepper ── */
  & .apr-cashup-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 18px; border-bottom: 1px solid var(--apr-cashup-line); }
  & .apr-cashup-brand { display: flex; align-items: center; gap: 9px; flex: none;
    & svg { width: 22px; height: 22px; color: var(--apr-cashup-accent); }
    & b { font-size: 15.5px; font-weight: 800; letter-spacing: -.01em; }
    & span { font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apr-cashup-accent); padding: 3px 7px; border-radius: 5px; background: color-mix(in oklch, var(--apr-cashup-accent) 14%, transparent); }
  }
  & .apr-cashup-meta { margin: 0; display: grid; font-size: 12px; color: var(--apr-cashup-mute); line-height: 1.3;
    & span:first-child { color: var(--apr-cashup-ink); font-weight: 600; }
  }
  & .apr-cashup-steps { margin-left: auto; display: flex; gap: 4px; counter-reset: apr-cashup-s;
    & button { position: relative; display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 14px 0 8px; border-radius: 999px; font-size: 13px; font-weight: 650; color: var(--apr-cashup-mute); border: 1px solid transparent; transition: color .2s, background-color .2s, border-color .2s; }
    & button i { width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; font: 750 11px var(--apr-cashup-mono); font-style: normal; border: 1.5px solid var(--apr-cashup-line2); transition: background-color .25s, border-color .25s, color .25s; }
    & button i svg { width: 12px; height: 12px; stroke-width: 3; }
    & button:hover { color: var(--apr-cashup-ink); }
    & button[aria-selected="true"] { color: var(--apr-cashup-ink); background: var(--apr-cashup-card); border-color: var(--apr-cashup-line2); }
    & button[aria-selected="true"] i { border-color: var(--apr-cashup-accent); color: var(--apr-cashup-accent); }
    & button.is-done i { background: var(--apr-cashup-good); border-color: var(--apr-cashup-good); color: var(--apr-cashup-bg); }
    & button + button::before { content: ""; position: absolute; left: -4px; top: 50%; width: 4px; height: 1.5px; background: var(--apr-cashup-line2); }
    & .apr-cashup-ledgertab { display: none; }
  }

  /* ── main ── */
  & .apr-cashup-main { grid-area: main; min-height: 0; overflow-y: auto; padding: 18px 20px 24px; scrollbar-width: thin; scrollbar-color: var(--apr-cashup-line2) transparent;
    & > * { animation: apr-cashup-in .4s var(--apr-cashup-ease); }
  }
  & .apr-cashup-hero { display: flex; align-items: flex-end; gap: 18px; margin-bottom: 16px; flex-wrap: wrap;
    & h2 { font-size: 13px; font-weight: 700; color: var(--apr-cashup-mute); }
    & .big { font: 800 clamp(34px, 4.6cqi, 50px)/1 var(--apr-cashup-mono); letter-spacing: -.055em; font-variant-numeric: tabular-nums; margin-top: 4px; }
    & .side { margin-left: auto; display: flex; gap: 18px; font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--apr-cashup-mute); }
    & .side b { display: block; font: 750 17px var(--apr-cashup-mono); letter-spacing: -.03em; text-transform: none; color: var(--apr-cashup-ink); margin-top: 2px; font-variant-numeric: tabular-nums; }
  }

  /* denominations: each row is a stepper plus a physical stack that grows with the count */
  & .apr-cashup-den { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; }
  & .apr-cashup-row { display: grid; grid-template-columns: 64px minmax(0, 1fr) auto 92px; gap: 14px; align-items: center; padding: 6px 10px 6px 8px; border-radius: 11px; transition: background-color .15s;
    &:hover, &:focus-within { background: var(--apr-cashup-card); }
    &.is-float { box-shadow: inset 3px 0 0 var(--apr-cashup-accent); }
  }
  & .apr-cashup-face { display: grid; place-items: center; height: 34px; border-radius: 5px; font: 800 14px var(--apr-cashup-mono); letter-spacing: -.03em; color: oklch(0.25 0.04 160); background: linear-gradient(135deg, oklch(0.84 0.06 150), oklch(0.74 0.07 155)); box-shadow: inset 0 0 0 2px oklch(0.92 0.04 150 / .6), inset 0 0 0 5px oklch(0.7 0.06 155 / .5);
    &.is-coin { width: 34px; justify-self: center; border-radius: 50%; font-size: 11px; background: radial-gradient(circle at 35% 30%, oklch(0.92 0.01 90), oklch(0.68 0.01 90)); box-shadow: inset 0 0 0 2px oklch(0.6 0.01 90 / .5); color: oklch(0.3 0.01 90); }
    &.is-cu { background: radial-gradient(circle at 35% 30%, oklch(0.8 0.1 55), oklch(0.56 0.11 45)); color: oklch(0.25 0.05 45); box-shadow: inset 0 0 0 2px oklch(0.5 0.1 45 / .5); }
  }
  & .apr-cashup-stack { position: relative; height: 34px; display: flex; align-items: center; gap: 10px; min-width: 0;
    & .bars { flex: 1; height: 22px; position: relative; border-radius: 4px; overflow: hidden; background: color-mix(in oklch, var(--apr-cashup-ink) 4%, transparent); }
    & .bars i { position: absolute; inset: 0 auto 0 0; width: calc(var(--f) * 100%); border-radius: 4px; transition: width .5s var(--apr-cashup-spring);
      background: repeating-linear-gradient(90deg, var(--c) 0 3px, color-mix(in oklch, var(--c), black 30%) 3px 4px); }
    & .bars b { position: absolute; inset: 0 auto 0 0; width: calc(var(--k) * 100%); border-right: 2px solid var(--apr-cashup-accent); transition: width .5s var(--apr-cashup-spring); }
    & .bars b.is-zero { border: 0; }
    & small { font: 600 11px var(--apr-cashup-mono); color: var(--apr-cashup-mute); white-space: nowrap; min-width: 92px; }
  }
  & .apr-cashup-stp { display: flex; align-items: center; border-radius: 10px; border: 1px solid var(--apr-cashup-line2); background: var(--apr-cashup-panel);
    & button { width: 32px; height: 34px; display: grid; place-items: center; font-size: 17px; font-weight: 700; border-radius: 9px; color: var(--apr-cashup-mute); }
    & button:hover:not(:disabled) { color: var(--apr-cashup-ink); background: var(--apr-cashup-card); }
    & input { width: 52px; height: 34px; border: 0; background: none; outline: none; text-align: center; font: 700 15px var(--apr-cashup-mono); font-variant-numeric: tabular-nums; -moz-appearance: textfield; }
    & input::-webkit-inner-spin-button { display: none; }
    &:focus-within { border-color: var(--apr-cashup-accent); }
  }
  & .apr-cashup-sub { text-align: right; font: 700 15px var(--apr-cashup-mono); font-variant-numeric: tabular-nums;
    &.is-bump { animation: apr-cashup-bump .35s var(--apr-cashup-spring); }
  }
  & .apr-cashup-float { margin-top: 16px; padding: 14px; border-radius: 14px; background: var(--apr-cashup-card); border: 1px solid var(--apr-cashup-line);
    & .hd { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
    & .hd p { margin: 0; font-size: 13px; color: var(--apr-cashup-mute); flex: 1; min-width: 200px; }
    & .hd p b { color: var(--apr-cashup-ink); font-family: var(--apr-cashup-mono); }
    & .chips { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
    & .chips span { font: 600 11.5px var(--apr-cashup-mono); padding: 4px 8px; border-radius: 6px; background: color-mix(in oklch, var(--apr-cashup-accent) 13%, transparent); color: var(--apr-cashup-accent); }
    & .chips.dep span { background: color-mix(in oklch, var(--apr-cashup-good) 12%, transparent); color: var(--apr-cashup-good); }
  }
  & .apr-cashup-btn { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 36px; padding: 0 14px; border-radius: 10px; font-size: 13px; font-weight: 700; border: 1px solid var(--apr-cashup-line2); white-space: nowrap; transition: background-color .2s, border-color .2s;
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { border-color: var(--apr-cashup-ink); }
    &.is-primary { background: var(--apr-cashup-accent); color: oklch(0.22 0.04 80); border-color: transparent; }
    &.is-primary:hover:not(:disabled) { background: color-mix(in oklch, var(--apr-cashup-accent), white 15%); }
  }

  /* reconcile */
  & .apr-cashup-grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
  & .apr-cashup-box { padding: 14px 16px; border-radius: 14px; background: var(--apr-cashup-card); border: 1px solid var(--apr-cashup-line);
    & h3 { font-size: 13.5px; font-weight: 750; margin-bottom: 10px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
    & dl { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: 7px 12px; font-size: 13px; }
    & dt { color: var(--apr-cashup-mute); } & dd { margin: 0; text-align: right; font-family: var(--apr-cashup-mono); font-variant-numeric: tabular-nums; }
    & .tot { padding-top: 8px; border-top: 1px dashed var(--apr-cashup-line2); color: var(--apr-cashup-ink); font-weight: 750; }
    & .po { display: grid; grid-template-columns: 1fr auto auto; gap: 8px; align-items: center; padding: 6px 0; border-bottom: 1px solid var(--apr-cashup-line); font-size: 13px; }
    & .po .rm { width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; color: var(--apr-cashup-mute); }
    & .po .rm:hover { color: var(--apr-cashup-bad); background: color-mix(in oklch, var(--apr-cashup-bad) 12%, transparent); }
    & .po .rm svg { width: 14px; height: 14px; }
    & form { display: grid; grid-template-columns: 1fr 90px auto; gap: 6px; margin-top: 10px; }
    & input[type="text"], & input:not([type]), & input[type="number"] { height: 34px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--apr-cashup-line2); background: var(--apr-cashup-panel); font-size: 13px; min-width: 0; }
    & input:focus { outline: 2px solid var(--apr-cashup-accent); outline-offset: 0; border-color: transparent; }
    & input[aria-invalid="true"] { border-color: var(--apr-cashup-bad); }
    & .err { grid-column: 1 / -1; margin: 0; font-size: 12px; color: var(--apr-cashup-bad); min-height: 1em; }
    & .settle { margin-top: 12px; width: 100%; }
    & .meter { height: 4px; border-radius: 2px; background: var(--apr-cashup-line); overflow: hidden; margin-top: 8px; }
    & .meter i { display: block; height: 100%; width: calc(var(--p) * 100%); background: var(--apr-cashup-good); transition: width .25s linear; }
  }
  & .apr-cashup-verdict { grid-column: 1 / -1; display: flex; align-items: center; gap: 16px; padding: 16px 18px; border-radius: 14px; border: 1px solid color-mix(in oklch, var(--v) 40%, transparent); background: color-mix(in oklch, var(--v) 9%, var(--apr-cashup-card)); --v: var(--apr-cashup-good);
    &[data-r="warn"] { --v: var(--apr-cashup-warn); } &[data-r="bad"] { --v: var(--apr-cashup-bad); }
    & .amt { font: 800 30px/1 var(--apr-cashup-mono); letter-spacing: -.05em; color: var(--v); font-variant-numeric: tabular-nums; }
    & p { margin: 0; font-size: 13px; color: var(--apr-cashup-mute); }
    & p b { color: var(--apr-cashup-ink); display: block; font-size: 15px; margin-bottom: 2px; }
    & textarea { flex: 1; min-height: 52px; padding: 8px 10px; border-radius: 9px; border: 1px solid var(--apr-cashup-line2); background: var(--apr-cashup-panel); font-size: 13px; resize: vertical; }
  }

  /* tips */
  & .apr-cashup-pool { display: flex; height: 30px; border-radius: 8px; overflow: hidden; gap: 2px; margin: 4px 0 14px;
    & i { flex: var(--w) 1 0; background: var(--c); transition: flex-grow .6s var(--apr-cashup-spring); position: relative; }
    & i span { position: absolute; left: 8px; top: 50%; translate: 0 -50%; font: 700 11px var(--apr-cashup-mono); color: oklch(0.2 0.03 165); white-space: nowrap; }
  }
  & .apr-cashup-staff { width: 100%; border-collapse: collapse; font-size: 13px;
    & th { text-align: left; font-size: 10px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--apr-cashup-mute); padding: 0 8px 6px; border-bottom: 1px solid var(--apr-cashup-line2); white-space: nowrap; }
    & th.r, & td.r { text-align: right; }
    & td { padding: 7px 8px; border-bottom: 1px solid var(--apr-cashup-line); }
    & .who { display: flex; align-items: center; gap: 9px; }
    & .who i { width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font: 750 11px var(--apr-cashup-mono); font-style: normal; background: var(--c); color: oklch(0.2 0.03 165); flex: none; }
    & .who small { display: block; font-size: 11.5px; color: var(--apr-cashup-mute); }
    & .hrs { width: 62px; height: 30px; padding: 0 8px; border-radius: 7px; border: 1px solid var(--apr-cashup-line2); background: var(--apr-cashup-panel); text-align: right; font: 600 13px var(--apr-cashup-mono); -moz-appearance: textfield; }
    & .hrs::-webkit-inner-spin-button { display: none; }
    & .hrs:focus { outline: 2px solid var(--apr-cashup-accent); outline-offset: 0; }
    & .share { font: 750 14px var(--apr-cashup-mono); font-variant-numeric: tabular-nums; }
    & .seg { display: inline-flex; padding: 2px; border-radius: 8px; background: var(--apr-cashup-panel); border: 1px solid var(--apr-cashup-line); }
    & .seg button { height: 26px; padding: 0 9px; border-radius: 6px; font-size: 11.5px; font-weight: 700; color: var(--apr-cashup-mute); }
    & .seg button[aria-checked="true"] { background: var(--apr-cashup-card); color: var(--apr-cashup-ink); box-shadow: 0 0 0 1px var(--apr-cashup-line2); }
    & tfoot td { font-weight: 750; border-bottom: 0; padding-top: 10px; }
  }

  /* sign-off */
  & .apr-cashup-checks { list-style: none; margin: 0 0 16px; padding: 0; display: grid; gap: 6px;
    & label { display: flex; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 12px; background: var(--apr-cashup-card); border: 1px solid var(--apr-cashup-line); cursor: pointer; font-size: 14px; transition: border-color .2s; }
    & label:has(:checked) { border-color: color-mix(in oklch, var(--apr-cashup-good) 45%, transparent); }
    & input[type="checkbox"] { width: 18px; height: 18px; margin: 0; flex: none; }
    & small { display: block; font-size: 12px; color: var(--apr-cashup-mute); }
    & .bag { margin-left: auto; width: 96px; height: 32px; padding: 0 8px; border-radius: 7px; border: 1px solid var(--apr-cashup-line2); background: var(--apr-cashup-panel); font: 600 13px var(--apr-cashup-mono); }
  }
  & .apr-cashup-sign { display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
    & .who { font-size: 13px; color: var(--apr-cashup-mute); } & .who b { display: block; color: var(--apr-cashup-ink); font-size: 15px; }
  }
  & .apr-cashup-hold { position: relative; margin-left: auto; height: 48px; padding: 0 22px; border-radius: 12px; overflow: hidden; font-size: 14.5px; font-weight: 750; background: var(--apr-cashup-card); border: 1px solid var(--apr-cashup-accent); color: var(--apr-cashup-accent); touch-action: none; user-select: none;
    &::before { content: ""; position: absolute; inset: 0; background: var(--apr-cashup-accent); transform-origin: 0 50%; transform: scaleX(var(--apr-cashup-hold)); }
    & span { position: relative; mix-blend-mode: normal; }
    &.is-holding { --apr-cashup-hold: 1; transition: --apr-cashup-hold 1.1s linear; color: oklch(0.22 0.04 80); }
    &:not(.is-holding) { transition: --apr-cashup-hold .25s var(--apr-cashup-ease), color .2s; }
    &:disabled { border-color: var(--apr-cashup-line2); color: var(--apr-cashup-mute); }
  }
  & .apr-cashup-hint { margin: 10px 0 0; font-size: 12.5px; color: var(--apr-cashup-mute); min-height: 1.4em; }
  & .apr-cashup-hint.is-err { color: var(--apr-cashup-warn); }

  /* ── ledger: the Z report prints as you work ── */
  & .apr-cashup-ledger { grid-area: ledger; min-height: 0; overflow-y: auto; padding: 16px 16px 20px; background: var(--apr-cashup-panel); border-left: 1px solid var(--apr-cashup-line); scrollbar-width: thin; scrollbar-color: var(--apr-cashup-line2) transparent; }
  & .apr-cashup-z { position: relative; padding: 16px 16px 22px; background: oklch(0.96 0.012 95); color: oklch(0.25 0.02 160); font: 12px/1.55 var(--apr-cashup-mono); font-variant-numeric: tabular-nums;
    -webkit-mask: radial-gradient(circle 5px at 50% 100%, transparent 98%, black) 50% 100% / 13px 100% repeat-x; mask: radial-gradient(circle 5px at 50% 100%, transparent 98%, black) 50% 100% / 13px 100% repeat-x;
    box-shadow: 0 20px 40px -20px black;
    & h3 { font: 800 13px var(--apr-cashup-mono); letter-spacing: .12em; text-align: center; }
    & .c { text-align: center; color: oklch(0.45 0.02 160); font-size: 11px; }
    & .ln { display: flex; justify-content: space-between; gap: 10px; }
    & .ln span:first-child { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
    & .ln.b { font-weight: 800; }
    & .ln.is-chg { animation: apr-cashup-ink .9s var(--apr-cashup-ease); }
    & hr { border: 0; border-top: 1px dashed oklch(0.25 0.02 160 / .4); margin: 8px 0; }
    & .neg { color: oklch(0.5 0.17 30); }
    & .pos { color: oklch(0.45 0.12 160); }
    & .stamp { position: absolute; right: 14px; top: 46%; padding: 6px 12px; border: 3px double oklch(0.5 0.17 30); border-radius: 6px; color: oklch(0.5 0.17 30); font: 800 15px var(--apr-cashup-mono); letter-spacing: .12em; rotate: -12deg; opacity: .85; animation: apr-cashup-stamp .5s cubic-bezier(.3, 1.6, .5, 1) backwards; }
  }

  & .apr-cashup-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 8px 18px; border-top: 1px solid var(--apr-cashup-line); font-size: 12px; color: var(--apr-cashup-mute);
    & span { display: flex; align-items: center; gap: 3px; }
  }
  & .apr-cashup-toast { position: absolute; left: 50%; bottom: 50px; z-index: 40; display: flex; align-items: center; gap: 14px; padding: 9px 10px 9px 16px; border-radius: 12px; background: var(--apr-cashup-ink); color: var(--apr-cashup-bg); font-size: 13px; font-weight: 600; max-width: calc(100% - 32px);
    box-shadow: 0 18px 40px -14px black; translate: -50% 18px; opacity: 0; pointer-events: none; transition: translate .4s var(--apr-cashup-spring), opacity .2s;
    & button { padding: 5px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 750; background: color-mix(in oklch, var(--apr-cashup-bg) 14%, transparent); flex: none; }
    &:not(.has-undo) button { display: none; }
    &.is-on { translate: -50% 0; opacity: 1; pointer-events: auto; }
  }

  @container apr-cashup (max-width: 1080px) {
    & .apr-cashup-steps button { padding: 0 10px 0 6px; }
    & .apr-cashup-meta { display: none; }
  }
  @container apr-cashup (max-width: 959px) {
    & .apr-cashup-app { grid-template-columns: minmax(0, 1fr) 270px; }
    & .apr-cashup-keys { display: none; }
    & .apr-cashup-steps .lbl { display: none; }
    & .apr-cashup-steps button[aria-selected="true"] .lbl { display: inline; }
    & .apr-cashup-row { grid-template-columns: 56px minmax(0, 1fr) auto 80px; gap: 10px; }
    & .apr-cashup-stack small { display: none; }
    & .apr-cashup-grid2 { grid-template-columns: 1fr; }
  }
  @container apr-cashup (max-width: 759px) {
    & .apr-cashup-app { grid-template: "top" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
    & .apr-cashup-ledger { grid-area: main; border-left: 0; }
    &:not([data-view="ledger"]) .apr-cashup-ledger, &[data-view="ledger"] .apr-cashup-main { display: none; }
    & .apr-cashup-top { flex-wrap: wrap; gap: 10px; padding: 10px 12px; }
    & .apr-cashup-steps { margin-left: 0; width: 100%; overflow-x: auto; scrollbar-width: none; }
    & .apr-cashup-steps button { flex: none; }
    & .apr-cashup-steps .apr-cashup-ledgertab { display: flex; }
    & .apr-cashup-main { padding: 14px 12px 20px; }
    & .apr-cashup-toast { bottom: 16px; }
    & .apr-cashup-staff .seg { display: none; }
  }
  @container apr-cashup (max-width: 460px) {
    & .apr-cashup-row { grid-template-columns: 46px auto minmax(0, 1fr); }
    & .apr-cashup-stack { display: none; }
    & .apr-cashup-hero .side { margin-left: 0; }
    & .apr-cashup-staff th:nth-child(2), & .apr-cashup-staff td:nth-child(2) { display: none; }
    & .apr-cashup-box form { grid-template-columns: 1fr 76px; }
    & .apr-cashup-box form button { grid-column: 1 / -1; }
  }

  @media (prefers-reduced-motion: reduce) {
    & .apr-cashup-main > * { animation: none; }
    & .apr-cashup-stack .bars i, & .apr-cashup-stack .bars b, & .apr-cashup-pool i { transition: none; }
    & .apr-cashup-sub.is-bump, & .apr-cashup-z .ln.is-chg, & .apr-cashup-z .stamp { animation: none; }
    & .apr-cashup-toast { transition: opacity .2s; }
    & .apr-cashup-hold.is-holding { transition: --apr-cashup-hold 1.1s steps(4); }
  }
}

@keyframes apr-cashup-in { from { opacity: 0; translate: 0 8px; } }
@keyframes apr-cashup-bump { 40% { scale: 1.12; color: var(--apr-cashup-accent); } }
@keyframes apr-cashup-ink { from { background: oklch(0.85 0.1 85 / .7); } }
@keyframes apr-cashup-stamp { from { opacity: 0; scale: 1.8; } }

js:
/* ── Copperwick close-out. All money is integer cents. The float is built greedily from the smallest
   denominations up, tip shares are split by points with largest-remainder rounding so they sum to
   the pool to the cent, and the Z report on the right reprints every line that changed. ── */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const money = (c, sign) => (c < 0 ? '−' : sign && c > 0 ? '+' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const plain = c => (c < 0 ? '-' : '') + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const IC = { check: '<path d="m5 12.5 4.5 4.5L19 7"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>', plus: '<path d="M12 5v14M5 12h14"/>', redo: '<path d="M4 12a8 8 0 1 0 2.4-5.7L4 8.5"/><path d="M4 4v4.5h4.5"/>', card: '<rect x="3" y="6" width="18" height="12" rx="2"/><path d="M3 10h18M7 15h4"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const DEN = [['$100', 10000, 'bill', 'oklch(0.72 0.08 150)'], ['$50', 5000, 'bill', 'oklch(0.72 0.08 150)'], ['$20', 2000, 'bill', 'oklch(0.72 0.08 150)'], ['$10', 1000, 'bill', 'oklch(0.72 0.08 150)'], ['$5', 500, 'bill', 'oklch(0.72 0.08 150)'], ['$1', 100, 'bill', 'oklch(0.72 0.08 150)'],
  ['25¢', 25, 'coin', 'oklch(0.78 0.01 90)'], ['10¢', 10, 'coin', 'oklch(0.78 0.01 90)'], ['5¢', 5, 'coin', 'oklch(0.78 0.01 90)'], ['1¢', 1, 'cu', 'oklch(0.66 0.11 50)']];
const STEPS = [['count', 'Count drawer'], ['reconcile', 'Reconcile'], ['tips', 'Tips'], ['sign', 'Sign off']];
const ROLE = { bar: ['Bartender', 1], back: ['Barback', 0.6], run: ['Food runner', 0.5] };
const POS = { sales: 131840, refunds: 1850, credit: 590420, debit: 93795, gift: 12000, house: 8600, cardTips: 121460 };
let S = {
  step: 'count', counts: [2, 3, 41, 18, 23, 64, 52, 37, 24, 61], float: 30000,
  paid: [{ id: 'p1', what: 'Ice delivery', c: 4200 }, { id: 'p2', what: 'Limes, corner grocer', c: 940 }],
  note: '', jar: 18600, settled: false, batch: null, bag: '', checks: { twice: false, sealed: false }, signed: null, seen: { count: true },
  staff: [
    { id: 's1', name: 'Noor Haddad', role: 'bar', h: 7.5, pay: 'payroll', c: 'oklch(0.8 0.12 85)' },
    { id: 's2', name: 'Tomás Reyes', role: 'bar', h: 8, pay: 'cash', c: 'oklch(0.78 0.13 160)' },
    { id: 's3', name: 'Ivy Chen', role: 'bar', h: 5, pay: 'payroll', c: 'oklch(0.75 0.1 220)' },
    { id: 's4', name: 'Malik Osei', role: 'back', h: 7, pay: 'cash', c: 'oklch(0.74 0.13 30)' },
    { id: 's5', name: 'Ruth Abernathy', role: 'run', h: 4.5, pay: 'cash', c: 'oklch(0.76 0.1 320)' }
  ]
};
const past = [];
const snap = () => { past.push(JSON.stringify(S)); if (past.length > 50) past.shift(); };
let pid = 10;

/* ── the arithmetic, in cents ── */
const counted = () => S.counts.reduce((s, n, i) => s + n * DEN[i][1], 0);
const paidOut = () => S.paid.reduce((s, p) => s + p.c, 0);
const expected = () => S.float + POS.sales - POS.refunds - paidOut();
const variance = () => counted() - expected();
const vRating = v => Math.abs(v) < 100 ? 'good' : Math.abs(v) <= 500 ? 'warn' : 'bad';
/* a float the next bartender can make change from: coins and small notes up to a par each,
   coins trimmed so they land on whole dollars, then larger notes; exact to the cent or reports the gap */
const PAR = [0, 0, 0, 8, 16, 40, 40, 50, 40, 99];
function buildFloat() {
  const C = S.counts, keep = C.map(() => 0);
  let best = 0, bq = 0, bd = 0, bn = 0, bp = 0;
  const cap = Math.min(S.float, 2500);
  for (let q = Math.min(C[6], PAR[6]); q >= 0; q--) for (let d = Math.min(C[7], PAR[7]); d >= Math.max(0, Math.min(C[7], PAR[7]) - 12); d--) for (let n = Math.min(C[8], PAR[8]); n >= Math.max(0, Math.min(C[8], PAR[8]) - 20); n--) {
    const c = 25 * q + 10 * d + 5 * n, p = (100 - c % 100) % 100, tot = c + p;
    if (p <= C[9] && tot <= cap && tot > best) { best = tot; bq = q; bd = d; bn = n; bp = p; }
  }
  keep[6] = bq; keep[7] = bd; keep[8] = bn; keep[9] = bp;
  let need = S.float - best;
  for (let i = 5; i >= 0 && need > 0; i--) { const take = Math.min(C[i], PAR[i] || 999, Math.floor(need / DEN[i][1])); keep[i] = take; need -= take * DEN[i][1]; }
  for (let i = 5; i >= 0 && need > 0; i--) { const take = Math.min(C[i] - keep[i], Math.floor(need / DEN[i][1])); keep[i] += take; need -= take * DEN[i][1]; }
  return { keep, short: need, kept: S.float - need };
}
const pool = () => POS.cardTips + S.jar;
function shares() {
  const pts = S.staff.map(p => p.h * ROLE[p.role][1]), tot = pts.reduce((a, b) => a + b, 0) || 1, P = pool();
  const exact = pts.map(p => P * p / tot), base = exact.map(Math.floor);
  let left = P - base.reduce((a, b) => a + b, 0);
  exact.map((e, i) => [e - base[i], i]).sort((a, b) => b[0] - a[0]).forEach(([, i]) => { if (left > 0) { base[i]++; left--; } });
  return { pts, tot, cents: base };
}
const cashTips = () => { const sh = shares(); return S.staff.reduce((s, p, i) => s + (p.pay === 'cash' ? sh.cents[i] : 0), 0); };
const deposit = () => counted() - buildFloat().kept + S.jar - cashTips();
const cardTotal = () => POS.credit + POS.debit + POS.gift + POS.house;
function missing() {
  const m = [];
  if (!S.checks.twice) m.push('confirm the second count');
  if (!S.checks.sealed) m.push('seal the deposit bag');
  if (!/^\d{4,}$/.test(S.bag)) m.push('enter the bag number');
  if (!S.settled) m.push('settle the card batch');
  if (vRating(variance()) === 'bad' && S.note.trim().length < 8) m.push('explain the variance');
  if (deposit() < 0) m.push('cash tips exceed the cash on hand');
  return m;
}

/* ── toast + tween ── */
const toastEl = $('.apr-cashup-toast');
let toastT = 0;
function toast(msg, undoable) {
  $('[data-msg]', toastEl).textContent = msg;
  toastEl.classList.toggle('has-undo', !!undoable);
  toastEl.classList.add('is-on');
  clearTimeout(toastT); toastT = setTimeout(() => toastEl.classList.remove('is-on'), 3400);
}
const tw = new WeakMap();
function tween(el, to) {
  if (!el) return;
  const from = +(el.dataset.n || to); el.dataset.n = to;
  if (RM.matches || from === to) { el.textContent = money(to); return; }
  const t0 = performance.now(), tok = {}; tw.set(el, tok);
  const f = now => {
    if (!root.isConnected) return;
    if (tw.get(el) !== tok) return;
    const k = Math.min(1, (now - t0) / 480), e = 1 - Math.pow(1 - k, 3);
    el.textContent = money(Math.round(from + (to - from) * e));
    if (k < 1) requestAnimationFrame(f);
  };
  requestAnimationFrame(f);
}

/* ── header ── */
function renderSteps() {
  const after = k => STEPS.slice(STEPS.findIndex(s => s[0] === k) + 1).some(s => S.seen[s[0]]);
  const done = { count: counted() > 0 && after('count'), reconcile: after('reconcile') && (vRating(variance()) !== 'bad' || S.note.trim().length >= 8), tips: after('tips'), sign: !!S.signed };
  $('.apr-cashup-steps').innerHTML = STEPS.map(([k, n], i) => '<button type="button" role="tab" data-step="' + k + '" aria-selected="' + (S.step === k) + '" class="' + (done[k] ? 'is-done' : '') + '"><i>' + (done[k] ? svg('check') : i + 1) + '</i><span class="lbl">' + n + '</span></button>').join('') +
    '<button type="button" role="tab" data-step="ledger" class="apr-cashup-ledgertab" aria-selected="' + (S.step === 'ledger') + '"><i>Z</i><span class="lbl">Report</span></button>';
}

/* ── steps ── */
function countHTML() {
  const F = buildFloat(), tot = counted();
  return '<div class="apr-cashup-hero"><div><h2>Counted in drawer</h2><div class="big" data-big>' + money(tot) + '</div></div>' +
    '<div class="side"><span>Expected<b>' + money(expected()) + '</b></span><span>Variance<b class="var" data-r="' + vRating(variance()) + '">' + money(variance(), true) + '</b></span></div></div>' +
    '<ul class="apr-cashup-den" aria-label="Denominations">' + DEN.map(([lab, v, kind, c], i) => {
      const n = S.counts[i], max = kind === 'bill' ? 60 : 80, f = Math.min(1, n / max), k = n ? Math.min(1, F.keep[i] / max) : 0;
      return '<li class="apr-cashup-row' + (F.keep[i] ? ' is-float' : '') + '" data-i="' + i + '"><span class="apr-cashup-face' + (kind !== 'bill' ? ' is-coin' : '') + (kind === 'cu' ? ' is-cu' : '') + '">' + lab + '</span>' +
        '<div class="apr-cashup-stack"><span class="bars"><i style="--f:' + f.toFixed(3) + ';--c:' + c + '"></i><b class="' + (k ? '' : 'is-zero') + '" style="--k:' + k.toFixed(3) + '"></b></span><small>' + (F.keep[i] ? F.keep[i] + ' stay · ' + (n - F.keep[i]) + ' bank' : n ? 'all to bank' : '') + '</small></div>' +
        '<div class="apr-cashup-stp"><button type="button" data-d="-1" aria-label="One fewer ' + lab + '"' + (n <= 0 ? ' disabled title="Already zero"' : '') + '>&minus;</button><input type="number" min="0" max="999" inputmode="numeric" value="' + n + '" data-n="' + i + '" aria-label="Number of ' + lab + '"><button type="button" data-d="1" aria-label="One more ' + lab + '">+</button></div>' +
        '<span class="apr-cashup-sub" data-sub="' + i + '">' + money(n * v) + '</span></li>';
    }).join('') + '</ul>' +
    '<div class="apr-cashup-float"><div class="hd"><p>Leave a <b>' + money(S.float) + '</b> float for tomorrow, built from the smallest notes and coins up. ' + (F.short ? '<b style="color:var(--apr-cashup-bad)">Short ' + money(F.short) + ' in small change.</b>' : 'Bank the rest.') + '</p>' +
    '<div class="apr-cashup-stp" role="group" aria-label="Float target"><button type="button" data-fl="-5000" aria-label="Float $50 less"' + (S.float <= 10000 ? ' disabled title="Minimum float is $100"' : '') + '>&minus;</button><input type="number" readonly value="' + S.float / 100 + '" aria-label="Float in dollars" tabindex="-1"><button type="button" data-fl="5000" aria-label="Float $50 more"' + (S.float >= 60000 ? ' disabled title="House rule: float is $600 at most"' : '') + '>+</button></div>' +
    '<button type="button" class="apr-cashup-btn" data-act="recount">' + svg('redo') + 'Blind recount</button></div>' +
    '<div class="chips">' + F.keep.map((n, i) => n ? '<span>' + n + ' × ' + DEN[i][0] + '</span>' : '').join('') + '</div>' +
    '<div class="chips dep">' + S.counts.map((n, i) => n - F.keep[i] ? '<span>' + (n - F.keep[i]) + ' × ' + DEN[i][0] + '</span>' : '').join('') + '</div></div>';
}
function reconcileHTML() {
  const v = variance(), r = vRating(v);
  const msg = r === 'good' ? ['Balanced', 'Within a dollar of what the POS expects.'] : r === 'warn' ? [v < 0 ? 'Short, within tolerance' : 'Over, within tolerance', 'House tolerance is $5.00 either way. A note is optional.'] : [v < 0 ? 'Short beyond tolerance' : 'Over beyond tolerance', 'Recount, check paid-outs, then explain it below before signing.'];
  return '<div class="apr-cashup-grid2">' +
    '<div class="apr-cashup-verdict" data-r="' + r + '"><span class="amt">' + money(v, true) + '</span><p><b>' + msg[0] + '</b>' + msg[1] + '</p>' +
    (r !== 'good' ? '<textarea data-note placeholder="What happened? e.g. comped round paid from drawer, not rung in" aria-label="Variance note">' + esc(S.note) + '</textarea>' : '') + '</div>' +
    '<section class="apr-cashup-box"><h3>Cash, per the POS</h3><dl>' +
    '<dt>Opening float</dt><dd>' + money(S.float) + '</dd><dt>Cash sales</dt><dd>' + money(POS.sales) + '</dd><dt>Cash refunds</dt><dd>' + money(-POS.refunds) + '</dd><dt>Paid-outs</dt><dd>' + money(-paidOut()) + '</dd>' +
    '<dt class="tot">Expected in drawer</dt><dd class="tot">' + money(expected()) + '</dd><dt>Counted</dt><dd>' + money(counted()) + '</dd></dl>' +
    '<h3 style="margin-top:16px">Paid-outs <span class="eyebrow">' + S.paid.length + '</span></h3>' +
    S.paid.map(p => '<div class="po" data-p="' + p.id + '"><span>' + esc(p.what) + '</span><span class="num">' + money(p.c) + '</span><button type="button" class="rm" data-act="rm-po" aria-label="Remove ' + esc(p.what) + '" title="Remove paid-out">' + svg('x') + '</button></div>').join('') +
    '<form class="po-add" novalidate><input name="what" placeholder="What for" autocomplete="off" aria-label="Paid-out reason"><input name="amt" type="number" step="0.01" min="0.01" placeholder="0.00" aria-label="Amount"><button type="submit" class="apr-cashup-btn">' + svg('plus') + 'Add</button><p class="err" data-err></p></form></section>' +
    '<section class="apr-cashup-box"><h3>Cards <span class="eyebrow">' + (S.settled ? 'Settled' : 'Open batch') + '</span></h3><dl>' +
    '<dt>Credit</dt><dd>' + money(POS.credit) + '</dd><dt>Debit</dt><dd>' + money(POS.debit) + '</dd><dt>Gift cards</dt><dd>' + money(POS.gift) + '</dd><dt>House accounts</dt><dd>' + money(POS.house) + '</dd>' +
    '<dt class="tot">Card total</dt><dd class="tot">' + money(cardTotal()) + '</dd><dt>Card tips</dt><dd>' + money(POS.cardTips) + '</dd></dl>' +
    '<button type="button" class="apr-cashup-btn is-primary settle" data-act="settle"' + (S.settled ? ' disabled title="Batch ' + S.batch + ' already settled"' : '') + '>' + svg('card') + (S.settled ? 'Settled · batch ' + S.batch : 'Settle card batch') + '</button><div class="meter" hidden><i style="--p:0"></i></div></section></div>';
}
function tipsHTML() {
  const sh = shares(), P = pool();
  return '<div class="apr-cashup-hero"><div><h2>Tip pool</h2><div class="big" data-big>' + money(P) + '</div></div><div class="side"><span>Card tips<b>' + money(POS.cardTips) + '</b></span><span>Tip jar<b><span class="apr-cashup-stp" style="display:inline-flex;vertical-align:middle"><button type="button" data-jar="-500" aria-label="Five dollars less"' + (S.jar < 500 ? ' disabled title="Jar is empty"' : '') + '>&minus;</button><input type="number" readonly tabindex="-1" value="' + (S.jar / 100).toFixed(2) + '" aria-label="Tip jar dollars" style="width:72px"><button type="button" data-jar="500" aria-label="Five dollars more">+</button></span></b></span></div></div>' +
    '<div class="apr-cashup-pool" aria-hidden="true">' + S.staff.map((p, i) => '<i style="--w:' + Math.max(1, sh.cents[i]) + ';--c:' + p.c + '"><span>' + p.name.split(' ')[0] + '</span></i>').join('') + '</div>' +
    '<table class="apr-cashup-staff"><thead><tr><th>Staff</th><th class="r">Points</th><th class="r">Hours</th><th class="r">Share</th><th>Paid as</th></tr></thead><tbody>' +
    S.staff.map((p, i) => '<tr data-s="' + p.id + '"><td><div class="who"><i style="--c:' + p.c + '">' + p.name.split(' ').map(w => w[0]).join('') + '</i><span>' + esc(p.name) + '<small>' + ROLE[p.role][0] + ' · ' + ROLE[p.role][1] + ' pt/h</small></span></div></td>' +
      '<td class="r num" data-pts="' + p.id + '">' + sh.pts[i].toFixed(2) + '</td><td class="r"><input class="hrs" type="number" min="0" max="16" step="0.25" value="' + p.h + '" data-h="' + p.id + '" aria-label="Hours for ' + esc(p.name) + '"></td>' +
      '<td class="r"><span class="share" data-sh="' + p.id + '">' + money(sh.cents[i]) + '</span></td>' +
      '<td><span class="seg" role="radiogroup" aria-label="Payout for ' + esc(p.name) + '"><button type="button" role="radio" data-pay="cash" aria-checked="' + (p.pay === 'cash') + '">Cash</button><button type="button" role="radio" data-pay="payroll" aria-checked="' + (p.pay === 'payroll') + '">Payroll</button></span></td></tr>').join('') +
    '</tbody><tfoot><tr><td>' + S.staff.length + ' people</td><td class="r num" data-pts-tot>' + sh.tot.toFixed(2) + '</td><td></td><td class="r num" data-sh-tot>' + money(sh.cents.reduce((a, b) => a + b, 0)) + '</td><td class="num" data-cash>' + money(cashTips()) + ' cash</td></tr></tfoot></table>';
}
function signHTML() {
  if (S.signed) return '<div class="apr-cashup-hero"><div><h2>Drawer closed</h2><div class="big">' + money(deposit()) + '</div></div><div class="side"><span>Bag<b>#' + esc(S.bag) + '</b></span><span>Signed<b>' + S.signed + '</b></span></div></div>' +
    '<p style="color:var(--apr-cashup-mute);margin:0 0 14px">Signed by Dana Whitlock. The deposit goes in the safe; the Z report prints with the bag.</p><button type="button" class="apr-cashup-btn" data-act="reopen">' + svg('redo') + 'Reopen drawer</button>';
  const m = missing(), varBad = vRating(variance()) === 'bad';
