const TAX = 0.08875, TIPS = [0, 18, 20, 22];
const GC = ['oklch(0.78 0.14 25)', 'oklch(0.83 0.13 85)', 'oklch(0.79 0.12 160)', 'oklch(0.76 0.11 245)', 'oklch(0.77 0.13 330)', 'oklch(0.8 0.1 200)', 'oklch(0.8 0.12 120)', 'oklch(0.75 0.1 290)'];
const GN = ['Amara', 'Jonas', 'Priyanka', 'Theo', 'Wen'];
const ITEMS = [
  ['i1', 'Albariño, bottle', 6400, [0, 1, 2]], ['i2', 'Oysters, half dozen', 2400, [0, 1, 2, 3, 4]], ['i3', 'Burrata', 1700, [1]], ['i4', 'Charred octopus', 2800, [0]],
  ['i5', 'Ribeye 14oz', 5600, [2]], ['i6', 'Halibut', 3800, [3]], ['i7', 'Mushroom risotto', 2700, [4]], ['i8', 'Negroni', 1500, [3]], ['i9', 'Negroni', 1500, [4]],
  ['i10', 'Sparkling water, 1 L', 800, [0, 1, 2, 3, 4]], ['i11', 'Olive oil cake', 1200, [1]], ['i12', 'Espresso × 2', 900, [0, 2]]
];
const IT = id => ITEMS.find(x => x[0] === id);
