  $('.apr-split-items').innerHTML = ITEMS.map(([id, name, c]) => {
    const sh = m === 'even' ? [] : S.shares[m][id], locked = sh.some(k => paidSet.has(k)), sel = S.sel === id && m !== 'even';
    const who = m === 'even' ? '<span>Split ' + S.ways + ' ways with everything else</span>' : sh.length ? sh.map(k => '<i style="--c:' + GC[k] + '">' + (k + 1) + '</i>').join('') + '<span>' + (sh.length > 1 ? 'shared ' + sh.length + ' ways · ' + money(Math.ceil(c / sh.length)) + ' each' : GN[sh[0]]) + '</span>' : '<span class="none">Unassigned · drag to a guest</span>';
    return '<li class="apr-split-it' + (locked ? ' is-paid' : '') + '" role="option" data-item="' + id + '" aria-selected="' + sel + '"><div class="face"><span class="q">1</span><span class="n">' + esc(name) + '</span><span class="p">' + money(c) + '</span><span class="who">' + who + '</span></div>' +
      (sel ? '<div class="chips" role="group" aria-label="Who shares ' + esc(name) + '">' + GN.map((n, k) => '<button type="button" data-tog="' + k + '" style="--c:' + GC[k] + '" aria-pressed="' + sh.includes(k) + '"' + (locked || paidSet.has(k) ? ' disabled title="' + (paidSet.has(k) ? GN[k] + ' has paid · void to change' : 'Part of a paid share · void it first') + '"' : ' title="' + (sh.includes(k) ? 'Take ' + n + ' off' : 'Add ' + n) + ' (' + (k + 1) + ')"') + '>' + (k + 1) + '</button>').join('') +
        '<button type="button" class="all" data-tog="all"' + (locked || paidSet.size ? ' disabled title="Someone has paid · can’t share with everyone"' : ' title="Share with the whole table (A)"') + '>All</button><button type="button" class="all" data-tog="none"' + (locked || !sh.length ? ' disabled title="' + (locked ? 'Part of a paid share' : 'Already unassigned') + '"' : ' title="Unassign (U)"') + '>None</button></div>' : '') + '</li>';
  }).join('');
  const u = $('[data-unassigned]');
  u.classList.toggle('is-ok', !M.unassigned);
  u.textContent = S.mode === 'even' ? ITEMS.length + ' items · ' + money(SUB) : M.unassigned ? money(M.unassigned) + ' unassigned' : 'All assigned';
}
function guestHTML(x, M) {
  const m = S.mode, c = GC[x.i % GC.length], name = m === 'even' ? 'Share ' + (x.i + 1) : GN[x.i], st = proc[m + x.i];
  const lines = m === 'even' ? '<p class="empty">' + money(SUB) + ' food and drink ÷ ' + S.ways + '</p>' : x.lines.length ? '<ul>' + x.lines.map(l => {
    const key = l.id + ':' + x.i, nw = !lastPortions.has(key);
    return '<li data-portion="' + l.id + '" data-g="' + x.i + '" class="' + (nw ? 'is-new' : '') + '" title="Drag to another guest, or back to the check"><span class="pie" style="--n:' + l.of + ';--c:' + c + '"></span><span>' + esc(l.name) + (l.of > 1 ? '<span class="fr">' + frac(l.of) + '</span>' : '') + '</span><span class="a">' + money(l.part) + '</span></li>';
