    '<dl><dt>Subtotal</dt><dd>' + money(x.sub) + '</dd><dt>Tax 8.875%</dt><dd>' + money(x.tax) + '</dd><dt>Tip ' + S.tip[m][x.i] + '%</dt><dd>' + money(x.tip) + '</dd><dt class="tot">Total</dt><dd class="tot">' + money(x.total) + '</dd></dl>' +
