css:
.apr-dispatch {
  --apr-dispatch-bg: oklch(0.975 0.005 240);
  --apr-dispatch-ink: oklch(0.25 0.02 255);
  --apr-dispatch-accent: oklch(0.66 0.19 42);
  --apr-dispatch-late: oklch(0.57 0.2 25);
  --apr-dispatch-ok: oklch(0.57 0.13 155);
  --apr-dispatch-land: oklch(0.955 0.008 100);
