  --apr-dispatch-ease: cubic-bezier(.2, .8, .2, 1);
  --apr-dispatch-spring: linear(0, .08 4%, .3 10%, .62 17%, .88 25%, 1.02 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  --apr-dispatch-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
