    & button[aria-selected="true"] { background: var(--apr-dispatch-card); color: var(--apr-dispatch-ink); box-shadow: 0 1px 3px oklch(0.3 0.03 255 / .15); }
    & b { font: 700 10.5px var(--apr-dispatch-mono); margin-left: 3px; }
