/* ── Kettle & Crumb dispatch. Couriers ride Manhattan routes on a street grid; every ETA in the list,
   the pins and the suggestions comes from the same route lengths the map draws, at each courier's
   speed, on a service clock running 30× real time. Assigning an order ranks couriers by the ETA
   they would actually deliver it at, and shows what it costs the orders already in their bag. ── */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
