const SIM = 30, M2PX = 6;
const AX = [70, 190, 310, 430, 550, 670], SY = [50, 150, 250, 350, 450];
const AVE = ['Lark', 'Mercer', 'Quill', 'Tanner', 'Ashby', 'Harbor'], ST = ['Ferry', 'Bell', 'Orchard', 'Crown', 'Pike'];
const K = [2, 2], P = n => [AX[n[0]], SY[n[1]]];
