const at = (h, m) => (h * 60 + m) * 60;
const ICON = { x: '<path d="M6 6l12 12M18 6 6 18"/>', bike: '<circle cx="6" cy="16" r="3.5"/><circle cx="18" cy="16" r="3.5"/><path d="M6 16l4-7h5l3 7M10 9 8 6H6"/>' };
const ic = k => '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">' + ICON[k] + '</svg>';

const C0 = [
