  { id: 'c2', name: 'Sana Idris', veh: 'Scooter', cap: 4, speed: 35, c: 'oklch(0.55 0.15 290)' },
  { id: 'c3', name: 'Becca Lund', veh: 'Bike', cap: 2, speed: 25, c: 'oklch(0.56 0.12 185)' },
  { id: 'c4', name: 'Omar Haddad', veh: 'Car', cap: 5, speed: 30, c: 'oklch(0.57 0.17 355)' }
