const O0 = [
  ['412', 'Okonkwo', 3, [4, 1], at(18, 51), at(19, 4), at(19, 26), 'out', 'c1'], ['414', 'Halvorsen', 2, [5, 3], at(18, 55), at(19, 6), at(19, 30), 'out', 'c1'],
  ['415', 'Delgado', 5, [0, 4], at(18, 58), at(19, 8), at(19, 33), 'out', 'c2'], ['416', 'Petrakis', 1, [1, 0], at(19, 1), at(19, 11), at(19, 36), 'ready', null],
  ['417', 'Mwangi', 4, [4, 4], at(19, 3), at(19, 15), at(19, 38), 'cooking', null], ['418', 'Fontaine', 2, [0, 1], at(19, 5), at(19, 17), at(19, 40), 'cooking', null],
  ['419', 'Lindgren', 3, [5, 0], at(19, 8), at(19, 20), at(19, 43), 'cooking', null],
  ['409', 'Baptiste', 2, [3, 0], at(18, 30), at(18, 42), at(19, 5), 'done', 'c3', at(19, 2)], ['410', 'Kim', 4, [1, 4], at(18, 33), at(18, 46), at(19, 4), 'done', 'c4', at(19, 7)],
  ['411', 'Asante', 1, [5, 1], at(18, 40), at(18, 51), at(19, 15), 'done', 'c2', at(19, 10)]
