const NAMES = ['Abara', 'Brandt', 'Costa', 'Dahl', 'Ekwueme', 'Fujita', 'Gallo', 'Hughes', 'Ilunga', 'Jovanović', 'Kask', 'Lemaire', 'Moreno', 'Nyberg', 'Oduya', 'Quarshie', 'Renner', 'Szabo'];
let S, simT, seqNo, nameI, past;
function reset() {
