    stats: { done: 38, onTime: 35, mins: 1026 },
    orders: O0.map(([no, name, n, node, placed, ready, promise, st, c, done]) => ({ id: 'o' + no, no, name, n, node, placed, ready, promise, st, c, at: done || null })),
    couriers: C0.map(c => Object.assign({ state: 'idle', route: null, t: 0, queue: [] }, c))
