  while (left.length) {
    left.sort((a, b) => { const pa = P(Or(a).node), pb = P(Or(b).node); return (Math.abs(pa[0] - cur[0]) + Math.abs(pa[1] - cur[1])) - (Math.abs(pb[0] - cur[0]) + Math.abs(pb[1] - cur[1])); });
    const id = left.shift(), nx = P(Or(id).node);
    d += Math.abs(nx[0] - cur[0]) + Math.abs(nx[1] - cur[1]);
